create or replace function public.pro_daily_log_duplicate_validate(p_input jsonb) returns void language plpgsql immutable security invoker set search_path=public,pg_temp as $$declare ref jsonb;begin
 if jsonb_typeof(p_input) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from array['action','actionId','childLogActionId','files','generation','grantId','sourceFileRevision','sourceLogId','sourceRevision','targetLogId','workId'] or p_input->>'action' is distinct from 'duplicate_with_files' or jsonb_typeof(p_input->'files') is distinct from 'array' or jsonb_array_length(p_input->'files') not between 1 and 20 or jsonb_typeof(p_input->'workId') is distinct from 'string' or length(p_input->>'workId') not between 1 and 160 or jsonb_typeof(p_input->'grantId') not in('string','null') or jsonb_typeof(p_input->'generation') not in('string','null') or jsonb_typeof(p_input->'sourceRevision') is distinct from 'number' or jsonb_typeof(p_input->'sourceFileRevision') is distinct from 'number' or not coalesce(p_input->>'sourceRevision'~'^[0-9]{1,10}$',false) or not coalesce(p_input->>'sourceFileRevision'~'^[0-9]{1,10}$',false) then raise exception 'Invalid duplicate body' using errcode='22023';end if;
 if(p_input->>'actionId')::uuid is null or(p_input->>'childLogActionId')::uuid is null or(p_input->>'sourceLogId')::uuid is null or(p_input->>'targetLogId')::uuid is null or p_input->>'sourceLogId'=p_input->>'targetLogId' or (p_input->>'grantId' is null)<>(p_input->>'generation' is null) or(p_input->>'sourceRevision')::numeric not between 1 and 2147483646 or(p_input->>'sourceFileRevision')::numeric not between 0 and 2147483646 then raise exception 'Invalid duplicate identities' using errcode='22023';end if;
 perform (p_input->>'grantId')::uuid,(p_input->>'generation')::uuid;
 for ref in select value from jsonb_array_elements(p_input->'files') loop
 if jsonb_typeof(ref) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(ref)key) is distinct from array['copyActionId','sha256','sourceFileId','targetFileId'] or not coalesce(ref->>'sha256'~'^[a-f0-9]{64}$',false) or(ref->>'sourceFileId')::uuid is null or(ref->>'targetFileId')::uuid is null or(ref->>'copyActionId')::uuid is null then raise exception 'Invalid selected file' using errcode='22023';end if;
 end loop;
 if(select count(distinct value->>'sourceFileId') from jsonb_array_elements(p_input->'files'))<>jsonb_array_length(p_input->'files') or(select count(distinct value->>'targetFileId') from jsonb_array_elements(p_input->'files'))<>jsonb_array_length(p_input->'files') or(select count(distinct x) from(select p_input->>'actionId' x union all select p_input->>'childLogActionId' union all select value->>'copyActionId' from jsonb_array_elements(p_input->'files'))s)<>jsonb_array_length(p_input->'files')+2 or exists(select 1 from jsonb_array_elements(p_input->'files')a cross join jsonb_array_elements(p_input->'files')b where a->>'sourceFileId'=b->>'targetFileId') then raise exception 'Duplicate identity collision' using errcode='22023';end if;
end $$;
create or replace function public.pro_daily_log_duplicate_canonical(p_value jsonb) returns text language plpgsql immutable security invoker set search_path=public,pg_temp as $$declare answer text;begin
 if jsonb_typeof(p_value)='object' then select '{'||coalesce(string_agg(to_jsonb(key)::text||':'||pro_daily_log_duplicate_canonical(value),',' order by key),'')||'}' into answer from jsonb_each(p_value);return answer;
 elsif jsonb_typeof(p_value)='array' then select '['||coalesce(string_agg(pro_daily_log_duplicate_canonical(value),',' order by ord),'')||']' into answer from jsonb_array_elements(p_value) with ordinality x(value,ord);return answer;end if;return p_value::text;end $$;
create or replace function public.pro_daily_log_duplicate_json(p_actor uuid,p_action uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$ select jsonb_build_object('input',d.input,'source',d.source_snapshot,'selectedFiles',coalesce((select jsonb_agg(f.source_snapshot order by f.position) from pro_daily_log_duplicate_files f where f.actor_id=d.actor_id and f.action_id=d.action_id),'[]'::jsonb),'phase',case when d.phase='finalizing' then 'pending' else d.phase end,'verifiedFileIds',coalesce((select jsonb_agg(f.target_file_id order by f.position) from pro_daily_log_duplicate_files f where f.actor_id=d.actor_id and f.action_id=d.action_id and f.verified),'[]'::jsonb),'result',d.result,'reservedAt',d.reserved_at,'abortedAt',d.aborted_at) from pro_daily_log_duplicates d where d.actor_id=p_actor and d.action_id=p_action $$;
create or replace function public.pro_daily_log_duplicate_auth(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_duplicates;ctx jsonb;begin
 if exists(select 1 from pro_daily_log_duplicate_retirements where duplicate_actor_id=p_actor and duplicate_action_id=p_action) then raise exception 'Owner retired this duplicate' using errcode='42501';end if;
 select * into d from pro_daily_log_duplicates where actor_id=p_actor and action_id=p_action;if not found then raise exception 'Duplicate unavailable' using errcode='42501';end if;
 ctx:=pro_daily_log_context(p_actor,d.work_id,d.grant_id,true);if (ctx->>'ownerId')::uuid<>d.owner_id or (ctx->>'sourceInviteId')::uuid is distinct from d.generation then raise exception 'Duplicate access changed' using errcode='42501';end if;
 -- Source visibility remains necessary even for immutable receipts.
 perform pro_daily_log_file_context(p_actor,d.work_id,d.source_log_id,d.grant_id,false,d.generation,true);
 return ctx;end $$;
create or replace function public.pro_daily_log_duplicate_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare aid uuid;a pro_daily_log_duplicate_aborts;ctx jsonb;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into a from pro_daily_log_duplicate_aborts where actor_id=p_actor and(action_id=p_action or duplicate_action_id=p_action) order by at limit 1;
 if found then
  aid:=a.duplicate_action_id;ctx:=pro_daily_log_context(p_actor,a.input->'duplicate'->>'workId',(a.input->'duplicate'->>'grantId')::uuid,true);
  if(ctx->>'sourceInviteId')::uuid is distinct from(a.input->'duplicate'->>'generation')::uuid then raise exception 'Generation changed' using errcode='42501';end if;
  perform pro_daily_log_file_context(p_actor,a.input->'duplicate'->>'workId',(a.input->'duplicate'->>'sourceLogId')::uuid,(a.input->'duplicate'->>'grantId')::uuid,false,(a.input->'duplicate'->>'generation')::uuid,true);
  return jsonb_build_object('attempt',pro_daily_log_duplicate_json(p_actor,aid),'abort',jsonb_build_object('input',a.input,'at',a.at));
 end if;
 if exists(select 1 from pro_daily_log_duplicate_retirements where duplicate_actor_id=p_actor and duplicate_action_id=p_action) then raise exception 'Owner retired this duplicate' using errcode='42501';end if;
 if not exists(select 1 from pro_daily_log_duplicates where actor_id=p_actor and action_id=p_action) then return jsonb_build_object('attempt',null,'abort',null);end if;
 perform pro_daily_log_duplicate_auth(p_actor,p_action);return jsonb_build_object('attempt',pro_daily_log_duplicate_json(p_actor,p_action),'abort',null);end $$;
create or replace function public.pro_daily_log_duplicate_file_guard() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_duplicates;f pro_daily_log_duplicate_files;slots integer;begin
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||new.owner_id::text||':'||new.work_id,0));
 if exists(select 1 from pro_daily_log_duplicate_aborts qa cross join lateral jsonb_array_elements(qa.input->'duplicate'->'files')r where r->>'targetFileId'=new.id::text) then raise exception 'Aborted file identity retired' using errcode='40001';end if;
 select * into f from pro_daily_log_duplicate_files where target_file_id=new.id;
 if found then select * into d from pro_daily_log_duplicates where actor_id=f.actor_id and action_id=f.action_id;
  if current_setting('pro.daily_duplicate',true) is distinct from d.actor_id::text||':'||d.action_id::text or d.phase<>'finalizing' or not f.materialized or new.owner_id<>d.owner_id or new.work_id<>d.work_id or new.log_id<>d.target_log_id or new.created_by<>d.actor_id or new.sha256<>f.source_snapshot->>'sha256' or new.object_path<>f.target_path then raise exception 'Reserved duplicate identity' using errcode='40001';end if;
 end if;
 select count(*) into slots from pro_daily_log_duplicate_files qs join pro_daily_log_duplicates qb using(actor_id,action_id) where qb.owner_id=new.owner_id and qb.work_id=new.work_id and qb.phase in('pending','finalizing') and not qs.materialized;
 if (select count(*) from pro_daily_log_files where owner_id=new.owner_id and work_id=new.work_id)+slots>=100 then raise exception 'File capacity including duplicate reservations exceeded' using errcode='40001';end if;
 return new;end $$;
