create or replace function public.pro_daily_log_duplicate_reserve(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;gid uuid;gen uuid;own uuid;wid text;lid uuid;target uuid;ctx jsonb;d pro_daily_log_duplicates;l pro_daily_logs;f pro_daily_log_files;ref jsonb;n integer:=0;slots integer;keytext text;begin
 if jsonb_typeof(p_input) is distinct from 'object' or (select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from array['action','actionId','childLogActionId','files','generation','grantId','sourceFileRevision','sourceLogId','sourceRevision','targetLogId','workId'] or p_input->>'action' is distinct from 'duplicate_with_files' or jsonb_typeof(p_input->'files') is distinct from 'array' or jsonb_array_length(p_input->'files') not between 1 and 20 or jsonb_typeof(p_input->'grantId') not in('string','null') or jsonb_typeof(p_input->'generation') not in('string','null') or jsonb_typeof(p_input->'sourceRevision') is distinct from 'number' or jsonb_typeof(p_input->'sourceFileRevision') is distinct from 'number' or not coalesce(p_input->>'sourceRevision'~'^[0-9]{1,10}$',false) or not coalesce(p_input->>'sourceFileRevision'~'^[0-9]{1,10}$',false) then raise exception 'Invalid duplicate' using errcode='22023';end if;
 perform pro_daily_log_duplicate_validate(p_input);
 aid:=(p_input->>'actionId')::uuid;gid:=(p_input->>'grantId')::uuid;gen:=(p_input->>'generation')::uuid;wid:=p_input->>'workId';lid:=(p_input->>'sourceLogId')::uuid;target:=(p_input->>'targetLogId')::uuid;
 if aid is null or target is null or lid is null or target=lid or (p_input->>'childLogActionId')::uuid is null or (gid is null)<>(gen is null) or (p_input->>'sourceRevision')::numeric not between 1 and 2147483646 or(p_input->>'sourceFileRevision')::numeric not between 0 and 2147483646 then raise exception 'Invalid duplicate identity' using errcode='22023';end if;
 ctx:=pro_daily_log_context(p_actor,wid,gid,true);own:=(ctx->>'ownerId')::uuid;if gen is distinct from(ctx->>'sourceInviteId')::uuid then raise exception 'Generation changed' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-duplicate:'||p_actor::text||':'||aid::text,0));
 -- All child action namespaces before the work advisory, never the reverse.
 for keytext in select k from(select 'pro-daily-log-action:'||p_actor::text||':'||(p_input->>'childLogActionId') k union all select 'pro-daily-log-file-action:'||p_actor::text||':'||(value->>'copyActionId') from jsonb_array_elements(p_input->'files'))s order by k loop perform pg_advisory_xact_lock(hashtextextended(keytext,0));end loop;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||own::text||':'||wid,0));if gid is not null then perform 1 from pro_team_grants where id=gid for share;end if;
 ctx:=pro_daily_log_context(p_actor,wid,gid,true);if gen is distinct from(ctx->>'sourceInviteId')::uuid then raise exception 'Generation changed' using errcode='42501';end if;
 if exists(select 1 from pro_daily_log_duplicate_aborts where actor_id=p_actor and duplicate_action_id=aid) then if exists(select 1 from pro_daily_log_duplicate_aborts where actor_id=p_actor and duplicate_action_id=aid and input->'duplicate' is distinct from p_input) then raise exception 'Duplicate identity reused' using errcode='22023';end if;return null;end if;
 select * into d from pro_daily_log_duplicates where actor_id=p_actor and action_id=aid;
 if found then perform pro_daily_log_duplicate_auth(p_actor,aid);if d.input is distinct from p_input then raise exception 'Duplicate action reused' using errcode='22023';end if;return pro_daily_log_duplicate_json(p_actor,aid);end if;
 if exists(select 1 from pro_daily_log_duplicate_aborts where actor_id=p_actor and action_id=aid) or exists(select 1 from pro_daily_log_actions where actor_id=p_actor and action_id=(p_input->>'childLogActionId')::uuid) then raise exception 'Action identity used' using errcode='40001';end if;
 if exists(select 1 from pro_daily_log_duplicates q where q.actor_id=p_actor and((q.input->>'childLogActionId')::uuid=(p_input->>'childLogActionId')::uuid or exists(select 1 from jsonb_array_elements(p_input->'files')r where r->>'copyActionId'=q.input->>'childLogActionId'))) or exists(select 1 from pro_daily_log_duplicate_files q where q.actor_id=p_actor and(q.copy_action_id=(p_input->>'childLogActionId')::uuid or exists(select 1 from jsonb_array_elements(p_input->'files')r where q.copy_action_id=(r->>'copyActionId')::uuid))) then raise exception 'Reserved child identity reused' using errcode='40001';end if;
 if exists(select 1 from pro_daily_logs where owner_id=own and work_id=wid and id=target) or exists(select 1 from pro_daily_log_duplicates where owner_id=own and work_id=wid and target_log_id=target) then raise exception 'Target identity used' using errcode='40001';end if;
 select * into l from pro_daily_logs where owner_id=own and work_id=wid and id=lid for share;if not found or not pro_daily_log_visible(p_actor,ctx,l) then raise exception 'Source unavailable' using errcode='42501';end if;
 if l.revision<>(p_input->>'sourceRevision')::integer or coalesce((select revision from pro_daily_log_file_heads where owner_id=own and work_id=wid and log_id=lid),0)<>(p_input->>'sourceFileRevision')::integer then raise exception 'Duplicate source changed' using errcode='40001';end if;
 select count(*) into slots from pro_daily_log_duplicate_files qs join pro_daily_log_duplicates qb using(actor_id,action_id) where qb.owner_id=own and qb.work_id=wid and qb.phase in('pending','finalizing') and not qs.materialized;
 if (select count(*) from pro_daily_log_files where owner_id=own and work_id=wid)+slots+jsonb_array_length(p_input->'files')>100 or (select count(*) from pro_daily_logs where owner_id=own and work_id=wid)+(select count(*) from pro_daily_log_duplicates qb where qb.owner_id=own and qb.work_id=wid and qb.phase in('pending','finalizing'))>=500 then raise exception 'Duplicate capacity exceeded' using errcode='40001';end if;
 if (select count(distinct value->>'sourceFileId') from jsonb_array_elements(p_input->'files'))<>jsonb_array_length(p_input->'files') or(select count(distinct value->>'targetFileId') from jsonb_array_elements(p_input->'files'))<>jsonb_array_length(p_input->'files') or(select count(distinct x) from(select aid::text x union all select p_input->>'childLogActionId' union all select value->>'copyActionId' from jsonb_array_elements(p_input->'files'))s)<>jsonb_array_length(p_input->'files')+2 then raise exception 'Duplicate identities' using errcode='22023';end if;
 insert into pro_daily_log_duplicates(actor_id,actor_name,action_id,owner_id,work_id,source_log_id,target_log_id,grant_id,generation,input,source_snapshot)values(p_actor,pro_team_name(p_actor),aid,own,wid,lid,target,gid,gen,p_input,pro_daily_log_json(l));
 for ref in select value from jsonb_array_elements(p_input->'files') loop
  if jsonb_typeof(ref) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(ref)key) is distinct from array['copyActionId','sha256','sourceFileId','targetFileId'] or not coalesce(ref->>'sha256'~'^[a-f0-9]{64}$',false) or(ref->>'sourceFileId')::uuid is null or(ref->>'targetFileId')::uuid is null or(ref->>'copyActionId')::uuid is null then raise exception 'Invalid selected file' using errcode='22023';end if;
  if exists(select 1 from pro_daily_log_files where id=(ref->>'targetFileId')::uuid) or exists(select 1 from pro_daily_log_file_actions where actor_id=p_actor and action_id=(ref->>'copyActionId')::uuid) or exists(select 1 from pro_daily_log_actions where actor_id=p_actor and action_id=(ref->>'copyActionId')::uuid) then raise exception 'Child identity used' using errcode='40001';end if;
  select * into f from pro_daily_log_files where owner_id=own and work_id=wid and log_id=lid and id=(ref->>'sourceFileId')::uuid and ready for share;if not found or f.sha256<>ref->>'sha256' then raise exception 'Selected source changed' using errcode='40001';end if;
  insert into pro_daily_log_duplicate_files values(p_actor,aid,n,f.id,(ref->>'targetFileId')::uuid,(ref->>'copyActionId')::uuid,pro_daily_log_file_json(f),f.object_path,own::text||'/'||(ref->>'targetFileId')||case when f.mime_type='application/pdf' then '.pdf' else '.jpg' end,false,false);n:=n+1;
 end loop;
 perform pro_daily_log_duplicate_auth(p_actor,aid);return pro_daily_log_duplicate_json(p_actor,aid);end $$;
create or replace function public.pro_daily_log_duplicate_stage(p_actor uuid,p_action uuid,p_file uuid default null,p_verified boolean default false) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_duplicates;items jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-duplicate:'||p_actor::text||':'||p_action::text,0));perform pro_daily_log_duplicate_auth(p_actor,p_action);select * into d from pro_daily_log_duplicates where actor_id=p_actor and action_id=p_action;
 if d.phase<>'pending' then return jsonb_build_object('attempt',pro_daily_log_duplicate_json(p_actor,p_action),'objects','[]'::jsonb);end if;
 if p_verified then update pro_daily_log_duplicate_files set verified=true where actor_id=p_actor and action_id=p_action and target_file_id=p_file;if not found then raise exception 'File unavailable' using errcode='22023';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('fileId',target_file_id,'sourcePath',source_path,'targetPath',target_path,'file',source_snapshot) order by position),'[]'::jsonb) into items from pro_daily_log_duplicate_files where actor_id=p_actor and action_id=p_action;
 perform pro_daily_log_duplicate_auth(p_actor,p_action);return jsonb_build_object('attempt',pro_daily_log_duplicate_json(p_actor,p_action),'objects',items);end $$;
create or replace function public.pro_daily_log_duplicate_finish(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_duplicates;f pro_daily_log_duplicate_files;keytext text;ctx jsonb;copy_input jsonb;log_result jsonb;file_result jsonb;files jsonb:='[]';head integer:=0;answer jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-duplicate:'||p_actor::text||':'||p_action::text,0));perform pro_daily_log_duplicate_auth(p_actor,p_action);select * into d from pro_daily_log_duplicates where actor_id=p_actor and action_id=p_action;
 if d.phase<>'pending' then return pro_daily_log_duplicate_json(p_actor,p_action);end if;
 for keytext in select k from(select 'pro-daily-log-action:'||p_actor::text||':'||(d.input->>'childLogActionId') k union all select 'pro-daily-log-file-action:'||p_actor::text||':'||copy_action_id::text from pro_daily_log_duplicate_files where actor_id=p_actor and action_id=p_action)s order by k loop perform pg_advisory_xact_lock(hashtextextended(keytext,0));end loop;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||d.owner_id::text||':'||d.work_id,0));if d.grant_id is not null then perform 1 from pro_team_grants where id=d.grant_id for share;end if;perform pro_daily_log_duplicate_auth(p_actor,p_action);
 if exists(select 1 from pro_daily_log_duplicate_files where actor_id=p_actor and action_id=p_action and not verified) then raise exception 'Files not verified' using errcode='40001';end if;
 if coalesce((select revision from pro_daily_log_file_heads where owner_id=d.owner_id and work_id=d.work_id and log_id=d.source_log_id),0)<>(d.input->>'sourceFileRevision')::integer or not exists(select 1 from pro_daily_logs where owner_id=d.owner_id and work_id=d.work_id and id=d.source_log_id and revision=(d.input->>'sourceRevision')::integer) then raise exception 'Source changed before completion' using errcode='40001';end if;
 if exists(select 1 from pro_daily_log_actions where actor_id=p_actor and action_id=(d.input->>'childLogActionId')::uuid) or exists(select 1 from pro_daily_log_duplicate_files qs join pro_daily_log_file_actions qa on qa.actor_id=qs.actor_id and qa.action_id=qs.copy_action_id where qs.actor_id=p_actor and qs.action_id=p_action) then raise exception 'Child action identity used' using errcode='40001';end if;
 perform set_config('pro.daily_duplicate',p_actor::text||':'||p_action::text,true);
 update pro_daily_log_duplicates set phase='finalizing' where actor_id=p_actor and action_id=p_action;
 log_result:=pro_daily_logs_mutate(p_actor,jsonb_build_object('action','duplicate','actionId',d.input->'childLogActionId','workId',d.work_id,'grantId',d.grant_id,'logId',d.source_log_id,'revision',d.input->'sourceRevision','targetLogId',d.target_log_id));
 for f in select * from pro_daily_log_duplicate_files where actor_id=p_actor and action_id=p_action order by position loop
  -- Materialize reservation in the SAME TX; quota guard counts remaining slots only.
  update pro_daily_log_duplicate_files set materialized=true where actor_id=p_actor and action_id=p_action and position=f.position;
  copy_input:=jsonb_build_object('action','copy','actionId',f.copy_action_id,'fileId',f.target_file_id,'workId',d.work_id,'logId',d.target_log_id,'grantId',d.grant_id,'generation',d.generation,'sourceLogId',d.source_log_id,'sourceFileId',f.source_file_id,'sourceSha256',f.source_snapshot->>'sha256');
  perform pro_daily_log_file_reserve(p_actor,copy_input,encode(sha256(convert_to(pro_daily_log_duplicate_canonical(copy_input),'UTF8')),'hex'));
  file_result:=pro_daily_log_file_ready(p_actor,f.copy_action_id);files:=files||jsonb_build_array(file_result->'file');head:=(file_result->>'revision')::integer;
 end loop;
 perform set_config('pro.daily_duplicate','',true);
 answer:=jsonb_build_object('action','duplicate_with_files','log',log_result->'log','files',files,'revision',head);
 update pro_daily_log_duplicates set phase='confirmed',result=answer where actor_id=p_actor and action_id=p_action;perform pro_daily_log_duplicate_auth(p_actor,p_action);return pro_daily_log_duplicate_json(p_actor,p_action);end $$;
-- Tombstones do not require a begin reservation. They close abort-before-begin races.
create or replace function public.pro_daily_log_duplicate_abort(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare inp jsonb;aid uuid;did uuid;keytext text;ctx jsonb;old pro_daily_log_duplicate_aborts;d pro_daily_log_duplicates;begin
 if jsonb_typeof(p_input) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from array['action','actionId','duplicate'] or p_input->>'action' is distinct from 'abort' or jsonb_typeof(p_input->'duplicate') is distinct from 'object' then raise exception 'Invalid abort' using errcode='22023';end if;
 inp:=p_input->'duplicate';perform pro_daily_log_duplicate_validate(inp);aid:=(p_input->>'actionId')::uuid;did:=(inp->>'actionId')::uuid;if aid is null or did is null or aid=did then raise exception 'Invalid abort identity' using errcode='22023';end if;
 ctx:=pro_daily_log_context(p_actor,inp->>'workId',(inp->>'grantId')::uuid,true);if (ctx->>'sourceInviteId')::uuid is distinct from(inp->>'generation')::uuid then raise exception 'Generation changed' using errcode='42501';end if;perform pro_daily_log_file_context(p_actor,inp->>'workId',(inp->>'sourceLogId')::uuid,(inp->>'grantId')::uuid,false,(inp->>'generation')::uuid,true);
 for keytext in select x from unnest(array[did::text,aid::text])x order by x loop perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-duplicate:'||p_actor::text||':'||keytext,0));end loop;
 if exists(select 1 from pro_daily_log_duplicates where actor_id=p_actor and action_id=aid) then raise exception 'Abort identity used' using errcode='40001';end if;
 select * into old from pro_daily_log_duplicate_aborts where actor_id=p_actor and action_id=aid;if found then if old.input is distinct from p_input then raise exception 'Abort identity reused' using errcode='22023';end if;return pro_daily_log_duplicate_read(p_actor,aid);end if;
 select * into old from pro_daily_log_duplicate_aborts where actor_id=p_actor and duplicate_action_id=did;if found then if old.input->'duplicate' is distinct from inp then raise exception 'Duplicate identity reused' using errcode='22023';end if;return jsonb_build_object('attempt',pro_daily_log_duplicate_json(p_actor,did),'abort',jsonb_build_object('input',old.input,'at',old.at));end if;
 select * into d from pro_daily_log_duplicates where actor_id=p_actor and action_id=did;if found then perform pro_daily_log_duplicate_auth(p_actor,did);if d.input is distinct from inp then raise exception 'Duplicate identity reused' using errcode='22023';end if;if d.phase='confirmed' then raise exception 'Duplicate already completed' using errcode='40001';end if;
  perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||d.owner_id::text||':'||d.work_id,0));update pro_daily_log_duplicates set phase='aborted',aborted_at=now() where actor_id=p_actor and action_id=did;
 end if;
 -- No file/object delete, even if an upload ACK was lost. Paths remain quarantined.
 insert into pro_daily_log_duplicate_aborts(actor_id,action_id,duplicate_action_id,owner_id,input,result) values(p_actor,aid,did,(ctx->>'ownerId')::uuid,p_input,'{}');
 perform pro_daily_log_context(p_actor,inp->>'workId',(inp->>'grantId')::uuid,true);return pro_daily_log_duplicate_read(p_actor,aid);end $$;
create or replace function public.pro_daily_log_duplicate_retire_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_daily_log_duplicate_retirements;begin
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_daily_log_duplicate_retirements where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('retirement',null);end if;perform pro_work_schedule_owner(p_actor,r.work_id);return jsonb_build_object('retirement',r.result);end $$;
create or replace function public.pro_daily_log_duplicate_retire(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_duplicates;r pro_daily_log_duplicate_retirements;aid uuid;da uuid;di uuid;wid text;answer jsonb;begin
 if jsonb_typeof(p_input) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from array['action','actionId','duplicateActionId','duplicateActorId','workId'] or p_input->>'action' is distinct from 'retire' then raise exception 'Invalid retirement' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;da:=(p_input->>'duplicateActorId')::uuid;di:=(p_input->>'duplicateActionId')::uuid;wid:=p_input->>'workId';if aid is null or da is null or di is null or aid=di then raise exception 'Invalid retirement identity' using errcode='22023';end if;perform pro_work_schedule_owner(p_actor,wid);
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-duplicate-retire:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-duplicate:'||da::text||':'||di::text,0));
 select * into r from pro_daily_log_duplicate_retirements where owner_id=p_actor and action_id=aid;if found then if r.input is distinct from p_input then raise exception 'Retirement identity reused' using errcode='22023';end if;return pro_daily_log_duplicate_retire_read(p_actor,aid);end if;
 if exists(select 1 from pro_daily_log_duplicates where actor_id=p_actor and action_id=aid) or exists(select 1 from pro_daily_log_duplicate_aborts where actor_id=p_actor and action_id=aid) then raise exception 'Retirement identity used' using errcode='40001';end if;
 select * into d from pro_daily_log_duplicates where actor_id=da and action_id=di and owner_id=p_actor and work_id=wid;if not found then raise exception 'Pending duplicate unavailable' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));perform pro_work_schedule_owner(p_actor,wid);
 if d.phase<>'pending' then raise exception 'Duplicate is no longer pending' using errcode='40001';end if;
 update pro_daily_log_duplicates set phase='aborted',aborted_at=now() where actor_id=da and action_id=di;
 answer:=jsonb_build_object('input',p_input,'at',now(),'attempt',pro_daily_log_duplicate_json(da,di));insert into pro_daily_log_duplicate_retirements values(p_actor,pro_team_name(p_actor),aid,da,di,wid,p_input,answer,now());perform pro_work_schedule_owner(p_actor,wid);return jsonb_build_object('retirement',answer);end $$;
create or replace function public.pro_daily_log_duplicate_pending(p_actor uuid,p_work text,p_after text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare anchor pro_daily_log_duplicates;items jsonb;cursor_value text;begin
 perform pro_work_schedule_owner(p_actor,p_work);
 if p_after is not null then select * into anchor from pro_daily_log_duplicates where owner_id=p_actor and work_id=p_work and phase='pending' and actor_id=split_part(p_after,':',1)::uuid and action_id=split_part(p_after,':',2)::uuid;if not found then raise exception 'Pending cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('duplicateActorId',q.actor_id,'duplicateActorName',q.actor_name,'attempt',pro_daily_log_duplicate_json(q.actor_id,q.action_id)) order by q.reserved_at desc,q.actor_id desc,q.action_id desc),'[]'::jsonb) into items from(select * from pro_daily_log_duplicates where owner_id=p_actor and work_id=p_work and phase='pending' and(p_after is null or(reserved_at,actor_id,action_id)<(anchor.reserved_at,anchor.actor_id,anchor.action_id)) order by reserved_at desc,actor_id desc,action_id desc limit 21)q;
 if jsonb_array_length(items)>20 then cursor_value:=(items->19->>'duplicateActorId')||':'||(items->19->'attempt'->'input'->>'actionId');items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_value);end $$;
create or replace function public.pro_daily_log_duplicate_action_guard() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_duplicates;begin
 select x.* into d from pro_daily_log_duplicates x where x.actor_id=new.actor_id and((x.input->>'childLogActionId')::uuid=new.action_id or exists(select 1 from pro_daily_log_duplicate_files f where f.actor_id=x.actor_id and f.action_id=x.action_id and f.copy_action_id=new.action_id)) limit 1;
 if found and(d.phase<>'finalizing' or current_setting('pro.daily_duplicate',true) is distinct from d.actor_id::text||':'||d.action_id::text or new.work_id<>d.work_id or new.owner_id<>d.owner_id or new.input->>'logId' not in(d.source_log_id::text,d.target_log_id::text)) then raise exception 'Reserved duplicate child action' using errcode='40001';end if;return new;end $$;
drop trigger if exists pro_daily_log_duplicate_action_guard on public.pro_daily_log_actions;
create trigger pro_daily_log_duplicate_action_guard before insert on public.pro_daily_log_actions for each row execute function pro_daily_log_duplicate_action_guard();
drop trigger if exists pro_daily_log_duplicate_action_guard on public.pro_daily_log_file_actions;
create trigger pro_daily_log_duplicate_action_guard before insert on public.pro_daily_log_file_actions for each row execute function pro_daily_log_duplicate_action_guard();
create or replace function public.pro_daily_log_duplicate_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if tg_table_name in('pro_daily_log_duplicate_aborts','pro_daily_log_duplicate_retirements') then raise exception 'Immutable abort receipt' using errcode='42501';end if;
 if tg_table_name='pro_daily_log_duplicate_files' then if(to_jsonb(new)-array['verified','materialized']) is distinct from(to_jsonb(old)-array['verified','materialized']) or old.verified and not new.verified or old.materialized and not new.materialized then raise exception 'Immutable duplicate provenance' using errcode='42501';end if;
 else if(to_jsonb(new)-array['phase','result','aborted_at']) is distinct from(to_jsonb(old)-array['phase','result','aborted_at']) or old.phase not in('pending','finalizing') then raise exception 'Immutable duplicate receipt' using errcode='42501';end if;end if;return new;end $$;
drop trigger if exists pro_daily_log_duplicate_immutable on public.pro_daily_log_duplicates;
create trigger pro_daily_log_duplicate_immutable before update on public.pro_daily_log_duplicates for each row execute function pro_daily_log_duplicate_immutable();
drop trigger if exists pro_daily_log_duplicate_immutable on public.pro_daily_log_duplicate_files;
create trigger pro_daily_log_duplicate_immutable before update on public.pro_daily_log_duplicate_files for each row execute function pro_daily_log_duplicate_immutable();
drop trigger if exists pro_daily_log_duplicate_immutable on public.pro_daily_log_duplicate_aborts;
create trigger pro_daily_log_duplicate_immutable before update on public.pro_daily_log_duplicate_aborts for each row execute function pro_daily_log_duplicate_immutable();
drop trigger if exists pro_daily_log_duplicate_immutable on public.pro_daily_log_duplicate_retirements;
create trigger pro_daily_log_duplicate_immutable before update on public.pro_daily_log_duplicate_retirements for each row execute function pro_daily_log_duplicate_immutable();
do $$declare t text;f record;begin
 foreach t in array array['pro_daily_log_duplicates','pro_daily_log_duplicate_files','pro_daily_log_duplicate_aborts','pro_daily_log_duplicate_retirements'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from public,anon,authenticated',t);execute format('grant all on table public.%I to service_role',t);end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro_daily_log_duplicate_%' loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;
end $$;
commit;

-- ===== company-daily-log-files-local.sql =====
-- LOCAL PRO ONLY. Copy a fixed company-library version into a saved private daily log.
-- No old function/column replacement, notifications, grants, publication or deletes.
begin;
create table if not exists public.pro_company_daily_log_file_actions(owner_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,actor_name text not null check(length(actor_name)<=160),work_id text not null,log_id uuid not null,source_file_id uuid not null,source_revision integer not null check(source_revision>0),target_file_id uuid not null unique,input jsonb not null,input_hash text not null check(input_hash~'^[a-f0-9]{64}$'),source_snapshot jsonb not null,source_path text not null,internal_input jsonb not null,result jsonb,reserved_at timestamptz not null default now(),primary key(owner_id,action_id),foreign key(owner_id,work_id,log_id,target_file_id) references pro_daily_log_files(owner_id,work_id,log_id,id) on delete cascade,check(source_file_id<>target_file_id));
create or replace function public.pro_company_daily_log_file_auth(p_actor uuid,p_action uuid) returns void language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_company_daily_log_file_actions;begin
 select * into r from pro_company_daily_log_file_actions where owner_id=p_actor and action_id=p_action;if not found then raise exception 'Copy reservation unavailable' using errcode='42501';end if;
 perform pro_daily_log_file_context(p_actor,r.work_id,r.log_id,null,true,null,true);
 perform pro_daily_file_retirement_guard(p_actor,p_action,r.target_file_id);
 if not exists(select 1 from pro_company_files where owner_id=p_actor and id=r.source_file_id and ready) then raise exception 'Company file access unavailable' using errcode='42501';end if;
 -- Current Pro/profile/log rights are mandatory. Metadata changes and archived
 -- source status do not redirect the immutable bytes/name captured at reserve.
end $$;
create or replace function public.pro_company_daily_log_file_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_company_daily_log_file_actions;begin
 if not coalesce(pro_appointment_enabled(p_actor),false) or not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_company_daily_log_file_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_company_daily_log_file_auth(p_actor,p_action);
 if r.result is null then return jsonb_build_object('receipt',null);end if;return jsonb_build_object('receipt',jsonb_build_object('inputHash',r.input_hash,'source',r.source_snapshot,'result',r.result));end $$;
create or replace function public.pro_company_daily_log_file_pending(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_company_daily_log_file_actions;target pro_daily_log_files;begin
 perform pro_company_daily_log_file_auth(p_actor,p_action);select * into r from pro_company_daily_log_file_actions where owner_id=p_actor and action_id=p_action;
 select * into target from pro_daily_log_files where owner_id=p_actor and work_id=r.work_id and log_id=r.log_id and id=r.target_file_id;if not found then raise exception 'Target unavailable' using errcode='42501';end if;
 return jsonb_build_object('input',r.input,'inputHash',r.input_hash,'source',r.source_snapshot,'sourcePath',r.source_path,'file',pro_daily_log_file_json(target),'targetPath',target.object_path,'result',r.result);end $$;
create or replace function public.pro_company_daily_log_file_reserve(p_actor uuid,p_input jsonb,p_input_hash text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;fid uuid;sid uuid;wid text;lid uuid;f pro_company_files;r pro_company_daily_log_file_actions;internal jsonb;ctx jsonb;begin
 if jsonb_typeof(p_input) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from array['action','actionId','logId','sourceFileId','sourceRevision','sourceSha256','targetFileId','workId'] or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'sourceFileId') is distinct from 'string' or jsonb_typeof(p_input->'targetFileId') is distinct from 'string' or jsonb_typeof(p_input->'logId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string' or p_input->>'action' is distinct from 'copy_from_company' or not coalesce(p_input_hash~'^[a-f0-9]{64}$',false) or jsonb_typeof(p_input->'sourceRevision') is distinct from 'number' or not coalesce(p_input->>'sourceRevision'~'^[0-9]{1,10}$',false) or(p_input->>'sourceRevision')::numeric not between 1 and 2147483647 or not coalesce(p_input->>'sourceSha256'~'^[a-f0-9]{64}$',false) then raise exception 'Invalid library copy' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;fid:=(p_input->>'targetFileId')::uuid;sid:=(p_input->>'sourceFileId')::uuid;wid:=p_input->>'workId';lid:=(p_input->>'logId')::uuid;if aid is null or fid is null or sid is null or lid is null or fid=sid then raise exception 'Invalid copy identity' using errcode='22023';end if;
 perform pro_daily_log_file_context(p_actor,wid,lid,null,true,null,true);
 -- Old file-action advisory first; the legacy facades use this exact lock.
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||aid::text,0));
 select * into r from pro_company_daily_log_file_actions where owner_id=p_actor and action_id=aid;if found then perform pro_company_daily_log_file_auth(p_actor,aid);if r.input is distinct from p_input or r.input_hash<>p_input_hash then raise exception 'Copy action reused' using errcode='22023';end if;return pro_company_daily_log_file_pending(p_actor,aid);end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-company-files:'||p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));
 perform pro_daily_log_file_context(p_actor,wid,lid,null,true,null,true);perform pro_daily_file_retirement_guard(p_actor,aid,fid);
 if exists(select 1 from pro_daily_log_file_actions where actor_id=p_actor and action_id=aid) or exists(select 1 from pro_daily_log_actions where actor_id=p_actor and action_id=aid) or exists(select 1 from pro_company_file_actions where actor_id=p_actor and action_id=aid) then raise exception 'Action identity used' using errcode='40001';end if;
 select * into f from pro_company_files where owner_id=p_actor and id=sid and ready for share;if not found then raise exception 'Company source unavailable' using errcode='42501';end if;
 if f.archived or f.revision<>(p_input->>'sourceRevision')::integer or f.sha256<>p_input->>'sourceSha256' then raise exception 'Company source changed' using errcode='40001';end if;perform pro_company_ancestors(p_actor,f.folder_id);
 internal:=jsonb_build_object('action','upload','actionId',aid,'fileId',fid,'workId',wid,'logId',lid,'grantId',null,'generation',null,'sourceName',f.name,'name',f.name,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'rawSha256',f.sha256,'sha256',f.sha256);
 perform pro_daily_log_file_reserve_guarded(p_actor,internal,encode(sha256(convert_to(pro_daily_log_duplicate_canonical(internal),'UTF8')),'hex'));
 insert into pro_company_daily_log_file_actions(owner_id,action_id,actor_name,work_id,log_id,source_file_id,source_revision,target_file_id,input,input_hash,source_snapshot,source_path,internal_input) values(p_actor,aid,pro_team_name(p_actor),wid,lid,sid,f.revision,fid,p_input,p_input_hash,pro_company_file_json(f),f.object_path,internal);
 perform pro_company_daily_log_file_auth(p_actor,aid);return pro_company_daily_log_file_pending(p_actor,aid);end $$;
create or replace function public.pro_company_daily_log_file_ready(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_company_daily_log_file_actions;ack jsonb;answer jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||p_action::text,0));perform pro_company_daily_log_file_auth(p_actor,p_action);select * into r from pro_company_daily_log_file_actions where owner_id=p_actor and action_id=p_action;
 if r.result is not null then return r.result;end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||r.work_id,0));perform pro_company_daily_log_file_auth(p_actor,p_action);
 ack:=pro_daily_log_file_ready_guarded(p_actor,p_action);perform pro_company_daily_log_file_auth(p_actor,p_action);
 answer:=jsonb_build_object('action','copy_from_company','source',r.source_snapshot,'file',ack->'file','revision',ack->'revision');update pro_company_daily_log_file_actions set result=answer where owner_id=p_actor and action_id=p_action;
 perform pro_company_daily_log_file_auth(p_actor,p_action);return answer;end $$;
-- Guard the HTTP legacy entry points under the same advisory as reservation.
-- Internal bridge uses the existing guarded RPCs and keeps their history intact.
create or replace function public.pro_company_daily_log_file_legacy_guard(p_actor uuid,p_action uuid) returns void language plpgsql security invoker set search_path=public,pg_temp as $$begin
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||p_action::text,0));if exists(select 1 from pro_company_daily_log_file_actions where owner_id=p_actor and action_id=p_action) then raise exception 'Use the company-copy receipt' using errcode='42501';end if;end $$;
create or replace function public.pro_company_daily_log_legacy_reserve(p_actor uuid,p_input jsonb,p_input_hash text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pro_company_daily_log_file_legacy_guard(p_actor,(p_input->>'actionId')::uuid);return pro_daily_log_file_reserve_guarded(p_actor,p_input,p_input_hash);end $$;
create or replace function public.pro_company_daily_log_legacy_pending(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pro_company_daily_log_file_legacy_guard(p_actor,p_action);return pro_daily_log_file_pending_guarded(p_actor,p_action);end $$;
create or replace function public.pro_company_daily_log_legacy_ready(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pro_company_daily_log_file_legacy_guard(p_actor,p_action);return pro_daily_log_file_ready_guarded(p_actor,p_action);end $$;
create or replace function public.pro_company_daily_log_legacy_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pro_company_daily_log_file_legacy_guard(p_actor,p_action);return pro_daily_log_file_action_read_guarded(p_actor,p_action);end $$;
create or replace function public.pro_company_daily_log_file_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin if old.result is not null or new.result is null or(to_jsonb(new)-'result') is distinct from(to_jsonb(old)-'result') then raise exception 'Immutable company copy receipt' using errcode='23514';end if;return new;end $$;
drop trigger if exists pro_company_daily_log_file_immutable on public.pro_company_daily_log_file_actions;
create trigger pro_company_daily_log_file_immutable before update on public.pro_company_daily_log_file_actions for each row execute function pro_company_daily_log_file_immutable();
alter table public.pro_company_daily_log_file_actions enable row level security;
revoke all on public.pro_company_daily_log_file_actions from public,anon,authenticated;
grant all on public.pro_company_daily_log_file_actions to service_role;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and(p.proname like 'pro_company_daily_log_file_%' or p.proname like 'pro_company_daily_log_legacy_%') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;

-- ===== request-pipeline-local.sql =====
-- LOCAL PRO ONLY: private commercial stages over existing appointment requests.
-- No existing writer/function/column replacement, public-state changes or sends.
begin;
create table if not exists public.pro_request_pipeline_heads(owner_id uuid primary key references profiles(id) on delete cascade,revision integer not null check(revision>=0));
create table if not exists public.pro_request_pipeline_stages(owner_id uuid not null references profiles(id) on delete cascade,id text not null,name text,position integer not null check(position between 0 and 17),hidden boolean not null default false,retired boolean not null default false,reassign_to_id text,primary key(owner_id,id),foreign key(owner_id,reassign_to_id) references pro_request_pipeline_stages(owner_id,id) deferrable initially deferred,check(hidden=(reassign_to_id is not null)),check(reassign_to_id is distinct from id),check(id not in('new','won') or not hidden),check(id not in('new','followed_up','connected','meeting_scheduled','estimate_sent','won') or not retired),check(case when id in('new','followed_up','connected','meeting_scheduled','estimate_sent','won') then name is null else name is not null and id~'^[a-f0-9-]{36}$' and length(btrim(name)) between 1 and 25 and name!~'[[:cntrl:]]' end));
create table if not exists public.pro_request_pipeline_states(owner_id uuid not null,request_id uuid not null,mode text not null check(mode in('automatic','manual')),stage_id text,revision integer not null check(revision>0),updated_at timestamptz not null default now(),primary key(owner_id,request_id),foreign key(owner_id,request_id) references pro_appointment_requests(owner_id,id) on delete cascade,foreign key(owner_id,stage_id) references pro_request_pipeline_stages(owner_id,id),check((mode='manual')=(stage_id is not null)));
create table if not exists public.pro_request_pipeline_actions(owner_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,actor_name text not null,at timestamptz not null default now(),primary key(owner_id,action_id));
create table if not exists public.pro_request_pipeline_history(owner_id uuid not null,request_id uuid not null,action_id uuid not null,action text not null check(action in('set_stage','return_auto','reassign_stage')),before_state jsonb not null,after_state jsonb not null,before_name text,after_name text,at timestamptz not null default now(),primary key(owner_id,request_id,action_id),foreign key(owner_id,request_id) references pro_appointment_requests(owner_id,id) on delete cascade);
create or replace function public.pro_request_pipeline_owner(p_actor uuid) returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$begin if not coalesce(pro_appointment_enabled(p_actor),false) or not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;end $$;
create or replace function public.pro_request_pipeline_catalog(p_actor uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare stages jsonb;begin perform pro_request_pipeline_owner(p_actor);
 with defaults as(select v id,(n-1)::integer position from unnest(array['new','followed_up','connected','meeting_scheduled','estimate_sent','won']) with ordinality x(v,n)),all_stages as(select d.id,coalesce(s.position,d.position)position,s.name,coalesce(s.hidden,false)hidden,s.reassign_to_id,true builtin from defaults d left join pro_request_pipeline_stages s on s.owner_id=p_actor and s.id=d.id union all select id,position,name,hidden,reassign_to_id,false from pro_request_pipeline_stages where owner_id=p_actor and not retired and id not in('new','followed_up','connected','meeting_scheduled','estimate_sent','won')) select jsonb_agg(jsonb_build_object('id',id,'builtin',builtin,'name',name,'position',position,'hidden',hidden,'reassignToId',reassign_to_id) order by position) into stages from all_stages;
 return jsonb_build_object('revision',coalesce((select revision from pro_request_pipeline_heads where owner_id=p_actor),0),'stages',stages);end $$;
create or replace function public.pro_request_pipeline_state(p_actor uuid,p_request uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$ select jsonb_build_object('requestId',p_request,'mode',coalesce(s.mode,'automatic'),'stageId',s.stage_id,'revision',coalesce(s.revision,0),'updatedAt',s.updated_at) from(select 1)dummy left join pro_request_pipeline_states s on s.owner_id=p_actor and s.request_id=p_request $$;
create or replace function public.pro_request_pipeline_auto(p_actor uuid,p_request uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_appointment_requests;q quotes;e pro_appointment_events;record jsonb;begin
 select * into r from pro_appointment_requests where owner_id=p_actor and id=p_request;if not found then raise exception 'Request unavailable' using errcode='P0002';end if;
 select x.* into q from pro_request_quotes m join quotes x on x.id=m.quote_id join professionals p on p.id=x.professional_id and p.profile_id=p_actor where m.owner_id=p_actor and m.request_id=r.id and m.client_user_id=r.client_user_id and x.client_id=r.client_user_id and x.professional_id=r.professional_id and x.deleted_at is null and m.accepted and x.status='accepted' and x.accepted_at is not null order by x.accepted_at desc,x.id limit 1;
 if found then return jsonb_build_object('stageId','won','evidence',jsonb_build_object('kind','accepted_quote','sourceId',q.id,'at',q.accepted_at));end if;
 select x.* into q from pro_request_quotes m join quotes x on x.id=m.quote_id join professionals p on p.id=x.professional_id and p.profile_id=p_actor where m.owner_id=p_actor and m.request_id=r.id and m.client_user_id=r.client_user_id and x.client_id=r.client_user_id and x.professional_id=r.professional_id and x.deleted_at is null and x.status in('sent','accepted','declined') order by x.created_at desc,x.id limit 1;
 if found then return jsonb_build_object('stageId','estimate_sent','evidence',jsonb_build_object('kind','shared_quote','sourceId',q.id,'at',q.created_at));end if;
 record:=pro_appointment_record(p_actor,r.id);
 if r.status in('confirmed','completed') and not coalesce((record->>'workCancelled')::boolean,false) and record->>'start' is not null then return jsonb_build_object('stageId','meeting_scheduled','evidence',jsonb_build_object('kind','meeting','sourceId',r.id,'at',record->>'start'));end if;
 select * into e from pro_appointment_events where request_id=r.id and actor_id=r.client_user_id and side='client' and action in('accept','reschedule') order by position desc limit 1;if found then return jsonb_build_object('stageId','connected','evidence',jsonb_build_object('kind','client_response','sourceId',e.position::text,'at',e.at));end if;
 select * into e from pro_appointment_events where request_id=r.id and actor_id=p_actor and side='provider' and action in('propose','confirm','decline') order by position desc limit 1;if found then return jsonb_build_object('stageId','followed_up','evidence',jsonb_build_object('kind','provider_response','sourceId',e.position::text,'at',e.at));end if;
 return jsonb_build_object('stageId','new','evidence',jsonb_build_object('kind','new','sourceId',r.id,'at',r.created_at));end $$;
create or replace function public.pro_request_pipeline_lead(p_actor uuid,p_request uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_appointment_requests;state jsonb;automatic jsonb;record jsonb;effective text;followup pro_request_followups;begin
 perform pro_request_pipeline_owner(p_actor);select * into r from pro_appointment_requests where owner_id=p_actor and id=p_request;if not found then raise exception 'Request unavailable' using errcode='P0002';end if;state:=pro_request_pipeline_state(p_actor,p_request);automatic:=pro_request_pipeline_auto(p_actor,p_request);record:=pro_appointment_record(p_actor,p_request);effective:=coalesce(state->>'stageId',automatic->>'stageId');select coalesce(reassign_to_id,effective) into effective from pro_request_pipeline_stages where owner_id=p_actor and id=effective;effective:=coalesce(effective,state->>'stageId',automatic->>'stageId');
 select * into followup from pro_request_followups where owner_id=p_actor and request_id=p_request;
 return jsonb_build_object('requestId',r.id,'position',r.position,'service',r.service,'clientName',r.client_name,'publicStatus',r.status,'requestRevision',r.revision,'createdAt',r.created_at,'updatedAt',r.updated_at,'start',record->'start','workId',r.work_id,'workCancelled',record->'workCancelled','state',state,'effectiveStageId',effective,'automaticStageId',automatic->'stageId','evidence',automatic->'evidence','followup',pro_request_followup_json(followup,r.id));end $$;
-- Relational filtering/counts/token first; only the visible twenty become full
-- lead JSON (including follow-up text). No all-owner business JSON workspace.
create index if not exists pro_request_pipeline_quote_lookup on public.pro_request_quotes(owner_id,request_id,quote_id);
create index if not exists pro_request_pipeline_history_page on public.pro_request_pipeline_history(owner_id,request_id,((after_state->>'revision')::integer) desc);
create or replace function public.pro_request_pipeline_read(p_actor uuid,p_stage text default null,p_query text default '',p_after uuid default null,p_snapshot text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare catalog jsonb;answer jsonb;actual_token text;cursor_valid boolean;begin
 perform pro_request_pipeline_owner(p_actor);catalog:=pro_request_pipeline_catalog(p_actor);if p_query is null or length(p_query)>100 or p_stage is not null and not exists(select 1 from jsonb_array_elements(catalog->'stages')s where s->>'id'=p_stage) then raise exception 'Invalid pipeline query' using errcode='22023';end if;
 with base as materialized(
  select r.id,r.position,r.service,r.client_name,r.status,r.revision,r.created_at,r.updated_at,r.requested_start,r.proposed_start,r.professional_id,r.client_user_id,r.work_id,pro_request_pipeline_auto(p_actor,r.id)automatic,coalesce(s.mode,'automatic')mode,s.stage_id,coalesce(s.revision,0)state_revision,s.updated_at state_updated,coalesce(f.revision,0)followup_revision,f.updated_at followup_updated,w.start work_start,w."end" work_end,w.stage work_stage,w.cancelled,
   (select max(position) from pro_appointment_events where request_id=r.id)event_position,
   (select md5(coalesce(string_agg(jsonb_build_array(q.id,q.status,q.updated_at,q.accepted_at,q.deleted_at,q.professional_id,q.client_id,m.client_user_id,m.accepted)::text,',' order by q.id),'')) from pro_request_quotes m join quotes q on q.id=m.quote_id where m.owner_id=p_actor and m.request_id=r.id)quote_token
  from pro_appointment_requests r left join pro_request_pipeline_states s on s.owner_id=p_actor and s.request_id=r.id left join pro_request_followups f on f.owner_id=p_actor and f.request_id=r.id left join pro_work w on w.user_id=p_actor and w.id=r.work_id
  where r.owner_id=p_actor and r.origin='booking' and(btrim(p_query)='' or position(lower(btrim(p_query)) in lower(r.service||' '||r.client_name))>0)
 ),resolved as materialized(select b.*,coalesce(s.reassign_to_id,b.stage_id,b.automatic->>'stageId')effective_stage from base b left join pro_request_pipeline_stages s on s.owner_id=p_actor and s.id=coalesce(b.stage_id,b.automatic->>'stageId')),
 metadata as(select md5(p_actor::text||coalesce(p_stage,'all')||p_query||catalog::text||coalesce(string_agg(jsonb_build_array(id,position,service,client_name,status,revision,created_at,updated_at,requested_start,proposed_start,professional_id,client_user_id,work_id,automatic,mode,stage_id,state_revision,state_updated,followup_revision,followup_updated,work_start,work_end,work_stage,cancelled,event_position,quote_token)::text,',' order by position desc),''))token from resolved),
 anchor as(select position from resolved where id=p_after and(p_stage is null or effective_stage=p_stage)),
 selected as materialized(select id,position from resolved where(p_stage is null or effective_stage=p_stage) and(p_after is null or position<(select position from anchor)) order by position desc limit 21),
 page as(select coalesce(jsonb_agg(pro_request_pipeline_lead(p_actor,id) order by position desc),'[]'::jsonb)items from(select id,position from selected order by position desc limit 20)v),
 counts as(select jsonb_agg(jsonb_build_object('stageId',s->>'id','count',(select count(*) from resolved where effective_stage=s->>'id')) order by(s->>'position')::integer)items from jsonb_array_elements(catalog->'stages')s)
 select jsonb_build_object('catalog',catalog,'items',page.items,'counts',counts.items,'nextCursor',case when(select count(*) from selected)>20 then(select id from selected order by position desc offset 19 limit 1)else null end,'snapshotToken',metadata.token),metadata.token,(p_after is null or exists(select 1 from anchor)) into answer,actual_token,cursor_valid from page cross join counts cross join metadata;
 if p_after is not null and(p_snapshot is null or p_snapshot<>actual_token or not cursor_valid) then raise exception 'Pipeline changed; reload results' using errcode='40001';end if;return answer;end $$;
create or replace function public.pro_request_pipeline_history_read(p_actor uuid,p_request uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare history jsonb;cursor_revision integer;cursor_id uuid;begin
 perform pro_request_pipeline_owner(p_actor);if not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=p_request) then raise exception 'Request unavailable' using errcode='P0002';end if;
 if p_after is not null then select(after_state->>'revision')::integer into cursor_revision from pro_request_pipeline_history where owner_id=p_actor and request_id=p_request and action_id=p_after;if not found then raise exception 'History cursor unavailable' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('actionId',h.action_id,'action',h.action,'at',h.at,'before',h.before_state,'after',h.after_state,'beforeName',h.before_name,'afterName',h.after_name) order by(h.after_state->>'revision')::integer desc),'[]'::jsonb) into history from(select * from pro_request_pipeline_history where owner_id=p_actor and request_id=p_request and(p_after is null or(after_state->>'revision')::integer<cursor_revision) order by(after_state->>'revision')::integer desc limit 21)h;
 if jsonb_array_length(history)>20 then cursor_id:=(history->19->>'actionId')::uuid;history:=history-20;end if;return jsonb_build_object('items',history,'nextCursor',cursor_id);end $$;
create or replace function public.pro_request_pipeline_detail(p_actor uuid,p_request uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare lead jsonb;history jsonb;begin lead:=pro_request_pipeline_lead(p_actor,p_request);history:=pro_request_pipeline_history_read(p_actor,p_request);return jsonb_build_object('catalog',pro_request_pipeline_catalog(p_actor),'lead',lead,'history',history->'items','nextCursor',history->'nextCursor');end $$;
create or replace function public.pro_request_pipeline_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_request_pipeline_actions;begin perform pro_request_pipeline_owner(p_actor);select * into r from pro_request_pipeline_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;if r.input?'requestId' and not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=(r.input->>'requestId')::uuid) then raise exception 'Request unavailable' using errcode='42501';end if;return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_request_pipeline_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare act text;aid uuid;sid text;rid uuid;expected text[];catalog_revision integer;current_revision integer;state_revision integer;catalog jsonb;old_catalog jsonb;before_json jsonb;after_json jsonb;answer jsonb;lead jsonb;auto jsonb;target text;stage_row pro_request_pipeline_stages;ref pro_request_pipeline_states;receipt pro_request_pipeline_actions;position_value integer;reassigned integer:=0;before_name text;after_name text;builtin_order text[];ids text[];begin
 perform pro_request_pipeline_owner(p_actor);
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'catalogRevision') is distinct from 'number' or not coalesce(p_input->>'catalogRevision'~'^[0-9]{1,10}$',false) or(p_input->>'catalogRevision')::numeric not between 0 and 2147483646 then raise exception 'Invalid pipeline operation' using errcode='22023';end if;
 act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;catalog_revision:=(p_input->>'catalogRevision')::integer;
 expected:=case act when 'stage_save' then array['action','actionId','catalogRevision','name','stageId'] when 'stage_reorder' then array['action','actionId','catalogRevision','stageIds'] when 'stage_visibility' then array['action','actionId','catalogRevision','hidden','reassignToId','stageId'] when 'stage_retire' then array['action','actionId','catalogRevision','reassignToId','stageId'] when 'set_stage' then array['action','actionId','catalogRevision','requestId','revision','stageId'] when 'return_auto' then array['action','actionId','catalogRevision','requestId','revision'] else null end;
 if expected is null or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from expected or aid is null then raise exception 'Unexpected pipeline fields' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pro_request_pipeline_owner(p_actor);
 select * into receipt from pro_request_pipeline_actions where owner_id=p_actor and action_id=aid;if found then if receipt.input is distinct from p_input then raise exception 'Pipeline action reused' using errcode='22023';end if;perform pro_request_pipeline_action_read(p_actor,aid);return receipt.result;end if;
 old_catalog:=pro_request_pipeline_catalog(p_actor);current_revision:=(old_catalog->>'revision')::integer;if current_revision<>catalog_revision then raise exception 'Lead stages changed' using errcode='40001';end if;
 -- Materialize defaults only on an explicit mutation. Reads never backfill.
 insert into pro_request_pipeline_heads values(p_actor,0) on conflict do nothing;
 insert into pro_request_pipeline_stages(owner_id,id,position) select p_actor,v,(n-1)::integer from unnest(array['new','followed_up','connected','meeting_scheduled','estimate_sent','won']) with ordinality x(v,n) on conflict do nothing;
 if act in('set_stage','return_auto') then
  if jsonb_typeof(p_input->'requestId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid request state' using errcode='22023';end if;
  rid:=(p_input->>'requestId')::uuid;if not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=rid) then raise exception 'Request unavailable' using errcode='42501';end if;
  before_json:=pro_request_pipeline_state(p_actor,rid);state_revision:=(before_json->>'revision')::integer;if state_revision<>(p_input->>'revision')::integer then raise exception 'Commercial stage changed' using errcode='40001';end if;
  if act='set_stage' then sid:=p_input->>'stageId';select * into stage_row from pro_request_pipeline_stages where owner_id=p_actor and id=sid and not hidden and not retired;if not found then raise exception 'Choose an active stage' using errcode='40001';end if;
  else sid:=null;end if;
  select name into before_name from pro_request_pipeline_stages where owner_id=p_actor and id=before_json->>'stageId';
  insert into pro_request_pipeline_states(owner_id,request_id,mode,stage_id,revision) values(p_actor,rid,case when act='set_stage' then 'manual' else 'automatic' end,sid,state_revision+1) on conflict(owner_id,request_id) do update set mode=excluded.mode,stage_id=excluded.stage_id,revision=excluded.revision,updated_at=now();
  after_json:=pro_request_pipeline_state(p_actor,rid);lead:=pro_request_pipeline_lead(p_actor,rid);catalog:=pro_request_pipeline_catalog(p_actor);select value into auto from jsonb_array_elements(catalog->'stages') where value->>'id'=lead->>'effectiveStageId';select name into after_name from pro_request_pipeline_stages where owner_id=p_actor and id=sid;
  insert into pro_request_pipeline_history values(p_actor,rid,aid,act,before_json,after_json,before_name,after_name,now());answer:=jsonb_build_object('action',act,'catalogRevision',current_revision,'state',after_json,'before',before_json,'stage',auto,'evidence',lead->'evidence');
 else
  if current_revision>=2147483647 then raise exception 'Stage catalogue revision exhausted' using errcode='40001';end if;
  if act='stage_save' then
   if jsonb_typeof(p_input->'stageId') is distinct from 'string' or jsonb_typeof(p_input->'name') is distinct from 'string' or length(btrim(p_input->>'name')) not between 1 and 25 or p_input->>'name'~'[[:cntrl:]]' then raise exception 'Invalid custom stage' using errcode='22023';end if;
   sid:=((p_input->>'stageId')::uuid)::text;select * into stage_row from pro_request_pipeline_stages where owner_id=p_actor and id=sid;
   if found then if stage_row.retired then raise exception 'Retired stage identity cannot be reused' using errcode='40001';end if;update pro_request_pipeline_stages set name=btrim(p_input->>'name') where owner_id=p_actor and id=sid;
   else if(select count(*) from pro_request_pipeline_stages where owner_id=p_actor and not retired and name is not null)>=12 then raise exception 'Twelve custom stages maximum' using errcode='40001';end if;select count(*) into position_value from pro_request_pipeline_stages where owner_id=p_actor and not retired;insert into pro_request_pipeline_stages(owner_id,id,name,position) values(p_actor,sid,btrim(p_input->>'name'),position_value);end if;
  elsif act='stage_reorder' then
   if jsonb_typeof(p_input->'stageIds') is distinct from 'array' or jsonb_array_length(p_input->'stageIds') not between 6 and 18 or exists(select 1 from jsonb_array_elements(p_input->'stageIds')x where jsonb_typeof(x)<>'string') then raise exception 'Invalid stage order' using errcode='22023';end if;
   select array_agg(value order by ord) into ids from jsonb_array_elements_text(p_input->'stageIds')with ordinality x(value,ord);select array_agg(value order by ord) into builtin_order from jsonb_array_elements_text(p_input->'stageIds')with ordinality x(value,ord) where value in('new','followed_up','connected','meeting_scheduled','estimate_sent','won');
   if builtin_order is distinct from array['new','followed_up','connected','meeting_scheduled','estimate_sent','won'] or cardinality(ids)<>(select count(distinct x) from unnest(ids)x) or cardinality(ids)<>(select count(*) from pro_request_pipeline_stages where owner_id=p_actor and not retired) or exists(select 1 from unnest(ids)x where not exists(select 1 from pro_request_pipeline_stages where owner_id=p_actor and id=x and not retired)) then raise exception 'Stage order changed' using errcode='40001';end if;
   update pro_request_pipeline_stages s set position=x.ord-1 from unnest(ids)with ordinality x(id,ord) where s.owner_id=p_actor and s.id=x.id;
  else
   if jsonb_typeof(p_input->'stageId') is distinct from 'string' or jsonb_typeof(p_input->'reassignToId') not in('string','null') then raise exception 'Invalid stage visibility' using errcode='22023';end if;
   sid:=p_input->>'stageId';target:=p_input->>'reassignToId';select * into stage_row from pro_request_pipeline_stages where owner_id=p_actor and id=sid and not retired;if not found then raise exception 'Stage unavailable' using errcode='40001';end if;
   if act='stage_retire' then if stage_row.name is null then raise exception 'Built-in stages cannot be retired' using errcode='22023';end if;
   elsif jsonb_typeof(p_input->'hidden') is distinct from 'boolean' or(p_input->>'hidden')::boolean=stage_row.hidden or sid in('new','won') and(p_input->>'hidden')::boolean then raise exception 'Invalid stage visibility transition' using errcode='22023';end if;
   if act='stage_retire' or(p_input->>'hidden')::boolean then
    if target is null or target=sid or not exists(select 1 from pro_request_pipeline_stages where owner_id=p_actor and id=target and not hidden and not retired) then raise exception 'Choose a visible replacement stage' using errcode='40001';end if;
    select name into after_name from pro_request_pipeline_stages where owner_id=p_actor and id=target;
    for ref in select * from pro_request_pipeline_states where owner_id=p_actor and mode='manual' and stage_id=sid order by request_id for update loop
     if ref.revision>=2147483647 then raise exception 'Request stage revision exhausted' using errcode='40001';end if;before_json:=pro_request_pipeline_state(p_actor,ref.request_id);update pro_request_pipeline_states set stage_id=target,revision=revision+1,updated_at=now() where owner_id=p_actor and request_id=ref.request_id;after_json:=pro_request_pipeline_state(p_actor,ref.request_id);insert into pro_request_pipeline_history values(p_actor,ref.request_id,aid,'reassign_stage',before_json,after_json,stage_row.name,after_name,now());reassigned:=reassigned+1;
    end loop;
    update pro_request_pipeline_stages set reassign_to_id=target where owner_id=p_actor and hidden and reassign_to_id=sid;
    update pro_request_pipeline_stages set hidden=true,reassign_to_id=target,retired=(act='stage_retire') where owner_id=p_actor and id=sid;
    if act='stage_retire' then with ordered as(select id,row_number()over(order by position)-1 pos from pro_request_pipeline_stages where owner_id=p_actor and not retired)update pro_request_pipeline_stages s set position=o.pos from ordered o where s.owner_id=p_actor and s.id=o.id;end if;
   else if target is not null then raise exception 'Showing a stage needs no reassignment' using errcode='22023';end if;update pro_request_pipeline_stages set hidden=false,reassign_to_id=null where owner_id=p_actor and id=sid;end if;
  end if;
  update pro_request_pipeline_heads set revision=current_revision+1 where owner_id=p_actor;catalog:=pro_request_pipeline_catalog(p_actor);answer:=jsonb_build_object('action',act,'catalog',catalog,'reassigned',reassigned);
 end if;
 perform pro_request_pipeline_owner(p_actor);insert into pro_request_pipeline_actions(owner_id,action_id,input,result,actor_name) values(p_actor,aid,p_input,answer,pro_team_name(p_actor));perform pro_request_pipeline_owner(p_actor);return answer;end $$;
create or replace function public.pro_request_pipeline_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin raise exception 'Immutable pipeline audit' using errcode='23514';end $$;
drop trigger if exists pro_request_pipeline_immutable on public.pro_request_pipeline_history;
create trigger pro_request_pipeline_immutable before update on public.pro_request_pipeline_history for each row execute function pro_request_pipeline_immutable();
drop trigger if exists pro_request_pipeline_immutable on public.pro_request_pipeline_actions;
create trigger pro_request_pipeline_immutable before update on public.pro_request_pipeline_actions for each row execute function pro_request_pipeline_immutable();
do $$declare t text;f record;begin foreach t in array array['pro_request_pipeline_heads','pro_request_pipeline_stages','pro_request_pipeline_states','pro_request_pipeline_actions','pro_request_pipeline_history'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro_request_pipeline_%' loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;

-- ===== lead-center-local.sql =====
-- LOCAL PRO ONLY. Manual private opportunities + archive preferences for real requests.
-- No synthetic bookings/accounts, messages, business ledger or old function replacements.
begin;
create table if not exists public.pro_lead_center_records(owner_id uuid not null references profiles(id) on delete cascade,kind text not null check(kind in('manual','request')),id uuid not null,request_id uuid,client_id text,title text,description text,address text,source_label text,project_type text,expected_start date,currency text,revenue_cents bigint,budget_cents bigint,profit_cents bigint,stage_mode text,stage_id text,revision integer not null check(revision>0),archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(owner_id,kind,id),foreign key(owner_id,request_id) references pro_appointment_requests(owner_id,id) on delete cascade,foreign key(owner_id,client_id) references pro_clients(user_id,id) deferrable initially deferred,foreign key(owner_id,stage_id) references pro_request_pipeline_stages(owner_id,id),check(case when kind='manual' then request_id is null and client_id is not null and title is not null and length(btrim(title)) between 1 and 160 and description is not null and length(description)<=2000 and address is not null and length(address)<=500 and source_label is not null and length(source_label)<=80 and project_type is not null and length(project_type)<=80 and currency is not null and currency in('CRC','USD') and stage_mode is not null and stage_mode in('automatic','manual') and ((stage_mode='manual')=(stage_id is not null)) else request_id is not null and request_id=id and client_id is null and title is null and description is null and address is null and source_label is null and project_type is null and expected_start is null and currency is null and revenue_cents is null and budget_cents is null and profit_cents is null and stage_mode is null and stage_id is null end),check(expected_start is null or expected_start between date'1900-01-01' and date'2100-12-31'),check(revenue_cents is null or revenue_cents between 0 and 1000000000000),check(budget_cents is null or budget_cents between 0 and 1000000000000),check(profit_cents is null or profit_cents between -1000000000000 and 1000000000000));
create index if not exists pro_lead_center_page on public.pro_lead_center_records(owner_id,kind,archived,created_at desc,id desc);
create table if not exists public.pro_lead_center_actions(owner_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,actor_name text not null,at timestamptz not null default now(),primary key(owner_id,action_id));
create table if not exists public.pro_lead_center_history(owner_id uuid not null,kind text not null,id uuid not null,action_id uuid not null,action text not null check(action in('create','update','set_stage','return_auto','archive','restore','reassign_stage')),before_item jsonb,after_item jsonb not null,before_name text,after_name text,at timestamptz not null default now(),primary key(owner_id,kind,id,action_id),foreign key(owner_id,kind,id) references pro_lead_center_records(owner_id,kind,id) on delete cascade);
-- This module-owned index intentionally switches from transaction time to causal revision.
drop index if exists public.pro_lead_center_history_page;
create index pro_lead_center_history_page on public.pro_lead_center_history(owner_id,kind,id,(coalesce((after_item->'manual'->>'revision')::integer,(after_item->'preference'->>'revision')::integer)) desc);
create table if not exists public.pro_lead_center_catalog_actions(owner_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,actor_name text not null,adopted_legacy boolean not null default false,at timestamptz not null default now(),primary key(owner_id,action_id));
create or replace function public.pro_lead_center_manual_json(p_row public.pro_lead_center_records) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('id',p_row.id,'clientId',p_row.client_id,'title',p_row.title,'description',p_row.description,'address',p_row.address,'sourceLabel',p_row.source_label,'forecast',jsonb_build_object('projectType',p_row.project_type,'expectedStart',case when p_row.expected_start is null then null else to_char(p_row.expected_start,'YYYY-MM-DD')end,'currency',p_row.currency,'revenueCents',p_row.revenue_cents,'budgetCents',p_row.budget_cents,'profitCents',p_row.profit_cents),'stageMode',p_row.stage_mode,'stageId',p_row.stage_id,'revision',p_row.revision,'archived',p_row.archived,'createdAt',p_row.created_at,'updatedAt',p_row.updated_at)$$;
create or replace function public.pro_lead_center_item(p_actor uuid,p_kind text,p_id uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_center_records;c pro_clients;begin
 perform pro_request_pipeline_owner(p_actor);if p_kind is null or p_kind not in('manual','request') then raise exception 'Invalid lead source' using errcode='22023';end if;select * into r from pro_lead_center_records where owner_id=p_actor and kind=p_kind and id=p_id;
 if p_kind='manual' then if not found then raise exception 'Opportunity unavailable' using errcode='P0002';end if;select * into c from pro_clients where user_id=p_actor and id=r.client_id;return jsonb_build_object('kind','manual','id',r.id,'manual',pro_lead_center_manual_json(r),'client',jsonb_build_object('id',c.id,'name',c.name,'archived',c.archived));end if;
 if not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=p_id) then raise exception 'Request unavailable' using errcode='P0002';end if;return jsonb_build_object('kind','request','id',p_id,'request',pro_request_pipeline_lead(p_actor,p_id),'preference',jsonb_build_object('revision',coalesce(r.revision,0),'archived',coalesce(r.archived,false),'updatedAt',r.updated_at));end $$;
-- Shared catalogue reader remains virtual. This helper only runs inside explicit writes.
create or replace function public.pro_lead_center_catalog_materialize(p_actor uuid) returns void language plpgsql security invoker set search_path=public,pg_temp as $$begin
 insert into pro_request_pipeline_heads values(p_actor,0) on conflict do nothing;insert into pro_request_pipeline_stages(owner_id,id,position)select p_actor,v,(n-1)::integer from unnest(array['new','followed_up','connected','meeting_scheduled','estimate_sent','won'])with ordinality x(v,n)on conflict do nothing;end $$;
create or replace function public.pro_lead_center_stage_guard() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if ((not old.hidden and new.hidden) or(not old.retired and new.retired)) and exists(select 1 from pro_lead_center_records where owner_id=old.owner_id and kind='manual' and stage_mode='manual' and stage_id=old.id) and coalesce(current_setting('pro.lead_center_catalog',true),'') not like old.owner_id::text||':%' then raise exception 'Use the mixed lead catalogue writer' using errcode='40001';end if;return new;end $$;
drop trigger if exists pro_lead_center_stage_guard on public.pro_request_pipeline_stages;
create trigger pro_lead_center_stage_guard before update on public.pro_request_pipeline_stages for each row execute function pro_lead_center_stage_guard();
create or replace function public.pro_lead_center_catalog_read_action(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_center_catalog_actions;begin perform pro_request_pipeline_owner(p_actor);select * into r from pro_lead_center_catalog_actions where owner_id=p_actor and action_id=p_action;if found then return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end if;return pro_request_pipeline_action_read(p_actor,p_action);end $$;
create or replace function public.pro_lead_center_catalog_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;act text;sid text;target text;r pro_lead_center_catalog_actions;old_receipt pro_request_pipeline_actions;ref pro_lead_center_records;answer jsonb;before_json jsonb;after_json jsonb;before_name text;after_name text;moved integer:=0;begin
 perform pro_request_pipeline_owner(p_actor);aid:=(p_input->>'actionId')::uuid;act:=p_input->>'action';if aid is null or act not in('stage_save','stage_reorder','stage_visibility','stage_retire') then raise exception 'Invalid catalogue action' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pro_request_pipeline_owner(p_actor);
 select * into r from pro_lead_center_catalog_actions where owner_id=p_actor and action_id=aid;if found then if r.input is distinct from p_input then raise exception 'Catalogue action reused' using errcode='22023';end if;return r.result;end if;
 if exists(select 1 from pro_lead_center_actions where owner_id=p_actor and action_id=aid) then raise exception 'Action identity already used' using errcode='40001';end if;
 select * into old_receipt from pro_request_pipeline_actions where owner_id=p_actor and action_id=aid;if found then
  if old_receipt.input is distinct from p_input then raise exception 'Catalogue action reused' using errcode='22023';end if;
  if exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and created_at<=old_receipt.at) then raise exception 'Legacy catalogue result cannot establish mixed provenance' using errcode='40001';end if;
  insert into pro_lead_center_catalog_actions values(p_actor,aid,p_input,old_receipt.result,pro_team_name(p_actor),true,now());perform pro_request_pipeline_owner(p_actor);return old_receipt.result;
 end if;
 sid:=p_input->>'stageId';target:=p_input->>'reassignToId';select name into before_name from pro_request_pipeline_stages where owner_id=p_actor and id=sid;select name into after_name from pro_request_pipeline_stages where owner_id=p_actor and id=target;
 perform set_config('pro.lead_center_catalog',p_actor::text||':'||aid::text,true);answer:=pro_request_pipeline_mutate(p_actor,p_input);
 if act='stage_retire' or act='stage_visibility' and(p_input->>'hidden')::boolean then
  for ref in select * from pro_lead_center_records where owner_id=p_actor and kind='manual' and stage_mode='manual' and stage_id=sid order by id for update loop
   if ref.revision>=2147483647 then raise exception 'Opportunity revision exhausted' using errcode='40001';end if;before_json:=pro_lead_center_item(p_actor,'manual',ref.id);update pro_lead_center_records set stage_id=target,revision=revision+1,updated_at=now() where owner_id=p_actor and kind='manual' and id=ref.id;after_json:=pro_lead_center_item(p_actor,'manual',ref.id);insert into pro_lead_center_history values(p_actor,'manual',ref.id,aid,'reassign_stage',before_json,after_json,before_name,after_name,now());moved:=moved+1;
  end loop;
 end if;
 perform set_config('pro.lead_center_catalog','',true);answer:=jsonb_set(answer,'{reassigned}',to_jsonb((answer->>'reassigned')::integer+moved));insert into pro_lead_center_catalog_actions values(p_actor,aid,p_input,answer,pro_team_name(p_actor),false,now());perform pro_request_pipeline_owner(p_actor);return answer;end $$;
create or replace function public.pro_lead_center_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_center_actions;begin perform pro_request_pipeline_owner(p_actor);select * into r from pro_lead_center_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_lead_center_item(p_actor,r.input->>'kind',(r.input->>'id')::uuid);return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_lead_center_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;lid uuid;act text;k text;expected text[];rev integer;catalog_revision integer;r pro_lead_center_records;prior pro_lead_center_actions;c pro_clients;before_json jsonb;after_json jsonb;answer jsonb;forecast jsonb;day date;sid text;mode_value text;before_name text;after_name text;begin
 perform pro_request_pipeline_owner(p_actor);
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'kind') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'id') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid opportunity operation' using errcode='22023';end if;
 act:=p_input->>'action';k:=p_input->>'kind';aid:=(p_input->>'actionId')::uuid;lid:=(p_input->>'id')::uuid;rev:=(p_input->>'revision')::integer;
 expected:=case act when 'create' then array['action','actionId','address','catalogRevision','clientId','description','forecast','id','kind','revision','sourceLabel','stageId','stageMode','title'] when 'update' then array['action','actionId','address','clientId','description','forecast','id','kind','revision','sourceLabel','title'] when 'set_stage' then array['action','actionId','catalogRevision','id','kind','revision','stageId'] when 'return_auto' then array['action','actionId','catalogRevision','id','kind','revision'] when 'archive' then array['action','actionId','id','kind','revision'] when 'restore' then array['action','actionId','id','kind','revision'] else null end;
 if aid is null or lid is null or expected is null or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from expected or k not in('manual','request') or k='request' and act not in('archive','restore') then raise exception 'Invalid source or fields' using errcode='22023';end if;
 -- Matches the existing contact writer: owner advisory precedes contact rows.
 -- No public request/work row is ever locked or updated by these private actions.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-center-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pro_request_pipeline_owner(p_actor);
 select * into prior from pro_lead_center_actions where owner_id=p_actor and action_id=aid;if found then if prior.input is distinct from p_input then raise exception 'Opportunity action reused' using errcode='22023';end if;perform pro_lead_center_action_read(p_actor,aid);return prior.result;end if;
 if exists(select 1 from pro_lead_center_catalog_actions where owner_id=p_actor and action_id=aid) or exists(select 1 from pro_request_pipeline_actions where owner_id=p_actor and action_id=aid) then raise exception 'Action identity already used' using errcode='40001';end if;
 catalog_revision:=(pro_request_pipeline_catalog(p_actor)->>'revision')::integer;
 if act in('create','set_stage','return_auto') then if jsonb_typeof(p_input->'catalogRevision') is distinct from 'number' or not coalesce(p_input->>'catalogRevision'~'^[0-9]{1,10}$',false) or(p_input->>'catalogRevision')::numeric not between 0 and 2147483646 then raise exception 'Invalid catalogue revision' using errcode='22023';end if;if catalog_revision<>(p_input->>'catalogRevision')::integer then raise exception 'Lead stages changed' using errcode='40001';end if;end if;
 if k='request' and not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=lid) then raise exception 'Request unavailable' using errcode='42501';end if;
 select * into r from pro_lead_center_records where owner_id=p_actor and kind=k and id=lid for update;
 if act='create' then if found or rev<>0 then raise exception 'Opportunity identity used' using errcode='40001';end if;
 else
  if k='manual' and not found then raise exception 'Opportunity unavailable' using errcode='42501';end if;
  before_json:=pro_lead_center_item(p_actor,k,lid);if coalesce(r.revision,0)<>rev then raise exception 'Opportunity changed' using errcode='40001';end if;
  if act not in('archive','restore') and r.archived then raise exception 'Restore before editing' using errcode='40001';end if;
 end if;
 if act in('create','update') then
  if jsonb_typeof(p_input->'clientId') is distinct from 'string' or length(p_input->>'clientId') not between 1 and 160 or jsonb_typeof(p_input->'title') is distinct from 'string' or length(btrim(p_input->>'title')) not between 1 and 160 or jsonb_typeof(p_input->'description') is distinct from 'string' or length(p_input->>'description')>2000 or jsonb_typeof(p_input->'address') is distinct from 'string' or length(p_input->>'address')>500 or jsonb_typeof(p_input->'sourceLabel') is distinct from 'string' or length(p_input->>'sourceLabel')>80 then raise exception 'Invalid opportunity details' using errcode='22023';end if;
  select * into c from pro_clients where user_id=p_actor and id=p_input->>'clientId' for share;if not found or c.archived and(act='create' or c.id is distinct from r.client_id) then raise exception 'Choose an active owned customer' using errcode='40001';end if;
  forecast:=p_input->'forecast';if jsonb_typeof(forecast) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(forecast)key) is distinct from array['budgetCents','currency','expectedStart','profitCents','projectType','revenueCents'] or jsonb_typeof(forecast->'projectType') is distinct from 'string' or length(forecast->>'projectType')>80 or jsonb_typeof(forecast->'currency') is distinct from 'string' or forecast->>'currency' not in('CRC','USD') or jsonb_typeof(forecast->'expectedStart') not in('string','null') then raise exception 'Invalid private forecast' using errcode='22023';end if;
  if forecast->>'expectedStart' is not null then if not(forecast->>'expectedStart'~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$') then raise exception 'Invalid expected date' using errcode='22023';end if;day:=(forecast->>'expectedStart')::date;if day not between date'1900-01-01' and date'2100-12-31' then raise exception 'Expected date out of range' using errcode='22023';end if;end if;
  if exists(select 1 from jsonb_each(forecast)f where key in('revenueCents','budgetCents','profitCents') and value<>'null'::jsonb and(jsonb_typeof(value)<>'number' or value::text!~'^-?[0-9]{1,13}$' or abs((value::text)::numeric)>1000000000000 or key<>'profitCents' and(value::text)::numeric<0)) then raise exception 'Invalid private money estimate' using errcode='22023';end if;
  if act='create' then mode_value:=p_input->>'stageMode';sid:=p_input->>'stageId';if jsonb_typeof(p_input->'stageMode') is distinct from 'string' or mode_value not in('automatic','manual') or jsonb_typeof(p_input->'stageId') not in('string','null') or(mode_value='manual')<>(sid is not null) then raise exception 'Invalid initial commercial stage' using errcode='22023';end if;
   if sid is not null then perform pro_lead_center_catalog_materialize(p_actor);if not exists(select 1 from pro_request_pipeline_stages where owner_id=p_actor and id=sid and not hidden and not retired) then raise exception 'Choose a visible stage' using errcode='40001';end if;end if;
   insert into pro_lead_center_records(owner_id,kind,id,client_id,title,description,address,source_label,project_type,expected_start,currency,revenue_cents,budget_cents,profit_cents,stage_mode,stage_id,revision) values(p_actor,'manual',lid,c.id,btrim(p_input->>'title'),btrim(p_input->>'description'),btrim(p_input->>'address'),btrim(p_input->>'sourceLabel'),btrim(forecast->>'projectType'),day,forecast->>'currency',(forecast->>'revenueCents')::bigint,(forecast->>'budgetCents')::bigint,(forecast->>'profitCents')::bigint,mode_value,sid,1);
  else update pro_lead_center_records set client_id=c.id,title=btrim(p_input->>'title'),description=btrim(p_input->>'description'),address=btrim(p_input->>'address'),source_label=btrim(p_input->>'sourceLabel'),project_type=btrim(forecast->>'projectType'),expected_start=day,currency=forecast->>'currency',revenue_cents=(forecast->>'revenueCents')::bigint,budget_cents=(forecast->>'budgetCents')::bigint,profit_cents=(forecast->>'profitCents')::bigint,revision=revision+1,updated_at=now() where owner_id=p_actor and kind='manual' and id=lid;end if;
 elsif act in('set_stage','return_auto') then
  sid:=case when act='set_stage' then p_input->>'stageId' else null end;if act='set_stage' then perform pro_lead_center_catalog_materialize(p_actor);if sid is null or not exists(select 1 from pro_request_pipeline_stages where owner_id=p_actor and id=sid and not hidden and not retired) then raise exception 'Choose a visible stage' using errcode='40001';end if;end if;
  update pro_lead_center_records set stage_mode=case when act='set_stage' then 'manual' else 'automatic' end,stage_id=sid,revision=revision+1,updated_at=now() where owner_id=p_actor and kind='manual' and id=lid;
 else
  if coalesce(r.archived,false)=(act='archive') then raise exception 'Opportunity archive state changed' using errcode='40001';end if;
  if k='request' and r.id is null then insert into pro_lead_center_records(owner_id,kind,id,request_id,revision,archived) values(p_actor,'request',lid,lid,1,true);
  else update pro_lead_center_records set archived=(act='archive'),revision=revision+1,updated_at=now() where owner_id=p_actor and kind=k and id=lid;end if;
 end if;
 perform pro_request_pipeline_owner(p_actor);
 if k='request' then select * into r from pro_lead_center_records where owner_id=p_actor and kind='request' and id=lid;after_json:=jsonb_set(before_json,'{preference}',jsonb_build_object('revision',r.revision,'archived',r.archived,'updatedAt',r.updated_at));else after_json:=pro_lead_center_item(p_actor,k,lid);end if;
 select name into before_name from pro_request_pipeline_stages where owner_id=p_actor and id=before_json->'manual'->>'stageId';select name into after_name from pro_request_pipeline_stages where owner_id=p_actor and id=after_json->'manual'->>'stageId';
 answer:=jsonb_build_object('action',act,'item',after_json,'before',before_json,'catalogRevision',catalog_revision);insert into pro_lead_center_history values(p_actor,k,lid,aid,act,before_json,after_json,before_name,after_name,now());insert into pro_lead_center_actions values(p_actor,aid,p_input,answer,pro_team_name(p_actor),now());perform pro_request_pipeline_owner(p_actor);return answer;end $$;
-- Relational source keys and fingerprints. Full item JSON is produced only for page20.
create or replace function public.pro_lead_center_sources(p_actor uuid,p_archived boolean,p_query text) returns table(kind text,id uuid,created_at timestamptz,effective_stage text,fingerprint text) language sql stable security invoker set search_path=public,pg_temp as $$
 with request_base as materialized(
  select r.*,pro_request_pipeline_auto(p_actor,r.id)automatic,s.stage_id,s.mode,s.revision state_revision,s.updated_at state_updated,coalesce(pref.archived,false)private_archived,coalesce(pref.revision,0)preference_revision,pref.updated_at preference_updated,f.revision followup_revision,f.updated_at followup_updated,w.start work_start,w."end" work_end,w.stage work_stage,w.cancelled,
   (select max(e.position) from pro_appointment_events e where e.request_id=r.id)event_position,
   (select md5(coalesce(string_agg(jsonb_build_array(q.id,q.status,q.updated_at,q.accepted_at,q.deleted_at,q.professional_id,q.client_id,m.client_user_id,m.accepted)::text,',' order by q.id),'')) from pro_request_quotes m join quotes q on q.id=m.quote_id where m.owner_id=p_actor and m.request_id=r.id)quote_token
  from pro_appointment_requests r left join pro_request_pipeline_states s on s.owner_id=p_actor and s.request_id=r.id left join pro_lead_center_records pref on pref.owner_id=p_actor and pref.kind='request' and pref.id=r.id left join pro_request_followups f on f.owner_id=p_actor and f.request_id=r.id left join pro_work w on w.user_id=p_actor and w.id=r.work_id
  where r.owner_id=p_actor and r.origin='booking' and coalesce(pref.archived,false)=p_archived and(btrim(p_query)='' or position(lower(btrim(p_query)) in lower(r.service||' '||r.client_name))>0)
 )
 select 'request',r.id,r.created_at,coalesce(s.reassign_to_id,r.stage_id,r.automatic->>'stageId'),md5(jsonb_build_array(r.id,r.created_at,r.updated_at,r.professional_id,r.client_user_id,r.client_name,r.service,r.status,r.revision,r.requested_start,r.proposed_start,r.work_id,r.work_start,r.work_end,r.work_stage,r.cancelled,r.automatic,r.stage_id,r.mode,r.state_revision,r.state_updated,r.private_archived,r.preference_revision,r.preference_updated,r.followup_revision,r.followup_updated,r.event_position,r.quote_token)::text)from request_base r left join pro_request_pipeline_stages s on s.owner_id=p_actor and s.id=coalesce(r.stage_id,r.automatic->>'stageId')
 union all
 select 'manual',r.id,r.created_at,coalesce(s.reassign_to_id,r.stage_id,'new'),md5(to_jsonb(r)::text||jsonb_build_array(c.id,c.name,c.archived)::text) from pro_lead_center_records r join pro_clients c on c.user_id=p_actor and c.id=r.client_id left join pro_request_pipeline_stages s on s.owner_id=p_actor and s.id=r.stage_id where r.owner_id=p_actor and r.kind='manual' and r.archived=p_archived and(btrim(p_query)='' or position(lower(btrim(p_query)) in lower(r.title||' '||c.name||' '||r.source_label))>0)
 $$;
create or replace function public.pro_lead_center_read(p_actor uuid,p_status text default 'active',p_stage text default null,p_query text default '',p_after text default null,p_snapshot text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare catalog jsonb;answer jsonb;actual_token text;cursor_valid boolean;begin
 perform pro_request_pipeline_owner(p_actor);catalog:=pro_request_pipeline_catalog(p_actor);if p_status is null or p_status not in('active','archived') or p_query is null or length(p_query)>100 or p_stage is not null and not exists(select 1 from jsonb_array_elements(catalog->'stages')s where s->>'id'=p_stage) or p_after is not null and p_after!~'^(manual|request):[a-f0-9-]{36}$' then raise exception 'Invalid lead query' using errcode='22023';end if;
 with sources as materialized(select * from pro_lead_center_sources(p_actor,p_status='archived',p_query)),
 metadata as(select md5(p_actor::text||p_status||coalesce(p_stage,'all')||p_query||catalog::text||coalesce(string_agg(jsonb_build_array(kind,id,created_at,effective_stage,fingerprint)::text,',' order by created_at desc,kind,id desc),''))token from sources),
 anchor as(select * from sources where kind=split_part(p_after,':',1) and id=split_part(p_after,':',2)::uuid and(p_stage is null or effective_stage=p_stage)),
 selected as materialized(select * from sources where(p_stage is null or effective_stage=p_stage) and(p_after is null or created_at<(select created_at from anchor) or created_at=(select created_at from anchor) and(kind>(select kind from anchor) or kind=(select kind from anchor) and id<(select id from anchor))) order by created_at desc,kind,id desc limit 21),
 page as(select coalesce(jsonb_agg(pro_lead_center_item(p_actor,kind,id) order by created_at desc,kind,id desc),'[]'::jsonb)items from(select * from selected order by created_at desc,kind,id desc limit 20)v),
 counts as(select jsonb_agg(jsonb_build_object('stageId',s->>'id','count',(select count(*) from sources where effective_stage=s->>'id')) order by(s->>'position')::integer)items from jsonb_array_elements(catalog->'stages')s)
 select jsonb_build_object('catalog',catalog,'items',page.items,'counts',counts.items,'nextCursor',case when(select count(*) from selected)>20 then(select kind||':'||id::text from selected order by created_at desc,kind,id desc offset 19 limit 1)else null end,'snapshotToken',metadata.token),metadata.token,(p_after is null or exists(select 1 from anchor)) into answer,actual_token,cursor_valid from page cross join counts cross join metadata;
 if p_after is not null and(p_snapshot is null or p_snapshot<>actual_token or not cursor_valid) then raise exception 'Leads changed; refresh before continuing' using errcode='40001';end if;return answer;end $$;
create or replace function public.pro_lead_center_history_read(p_actor uuid,p_kind text,p_id uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare items jsonb;anchor_revision integer;cursor_id uuid;begin
 perform pro_lead_center_item(p_actor,p_kind,p_id);
 if p_after is not null then select coalesce((after_item->'manual'->>'revision')::integer,(after_item->'preference'->>'revision')::integer) into anchor_revision from pro_lead_center_history where owner_id=p_actor and kind=p_kind and id=p_id and action_id=p_after;if not found then raise exception 'Lead history cursor unavailable' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('actionId',h.action_id,'action',h.action,'at',h.at,'before',h.before_item,'after',h.after_item,'beforeName',h.before_name,'afterName',h.after_name) order by coalesce((h.after_item->'manual'->>'revision')::integer,(h.after_item->'preference'->>'revision')::integer) desc),'[]'::jsonb) into items from(select * from pro_lead_center_history where owner_id=p_actor and kind=p_kind and id=p_id and(p_after is null or coalesce((after_item->'manual'->>'revision')::integer,(after_item->'preference'->>'revision')::integer)<anchor_revision) order by coalesce((after_item->'manual'->>'revision')::integer,(after_item->'preference'->>'revision')::integer) desc limit 21)h;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'actionId')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_lead_center_detail(p_actor uuid,p_kind text,p_id uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare item jsonb;history jsonb;begin item:=pro_lead_center_item(p_actor,p_kind,p_id);history:=pro_lead_center_history_read(p_actor,p_kind,p_id);return jsonb_build_object('catalog',pro_request_pipeline_catalog(p_actor),'item',item,'history',history->'items','nextCursor',history->'nextCursor');end $$;
create or replace function public.pro_lead_center_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin raise exception 'Immutable lead history/receipt' using errcode='23514';end $$;
do $$declare t text;f record;begin
 foreach t in array array['pro_lead_center_records','pro_lead_center_actions','pro_lead_center_history','pro_lead_center_catalog_actions']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;
 foreach t in array array['pro_lead_center_actions','pro_lead_center_history','pro_lead_center_catalog_actions']loop execute format('drop trigger if exists pro_lead_center_immutable on public.%I',t);execute format('create trigger pro_lead_center_immutable before update on public.%I for each row execute function pro_lead_center_immutable()',t);end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro_lead_center_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;

-- ===== manual-lead-quotes-local.sql =====
-- LOCAL PRO ONLY. Real direct quotation + immutable manual-opportunity origin.
-- No synthetic client account/appointment, delivery, acceptance, invoice or debt.
begin;
create unique index if not exists pro_manual_lead_quote_contact_identity on public.pro_quote_links(user_id,"quoteId","clientId");
create table if not exists public.pro_manual_lead_quotes(owner_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,lead_kind text not null default 'manual' check(lead_kind='manual'),lead_id uuid not null,source_lead_revision integer not null check(source_lead_revision>0),source_client_id text not null,source_snapshot jsonb not null,quote_id uuid not null unique,quote_id_text text generated always as(quote_id::text)stored,input jsonb not null,result jsonb not null,actor_name text not null,created_at timestamptz not null default now(),primary key(owner_id,action_id),foreign key(owner_id,lead_kind,lead_id) references pro_lead_center_records(owner_id,kind,id) on delete cascade,foreign key(quote_id) references quotes(id) deferrable initially deferred,foreign key(owner_id,quote_id_text,source_client_id) references pro_quote_links(user_id,"quoteId","clientId") deferrable initially deferred);
create index if not exists pro_manual_lead_quote_page on public.pro_manual_lead_quotes(owner_id,lead_id,created_at desc,quote_id desc);
create or replace function public.pro_manual_lead_quote_dto(p_doc jsonb) returns jsonb language sql immutable security invoker set search_path=public,pg_temp as $$select jsonb_object_agg(k,coalesce(p_doc->k,'null'::jsonb)) from unnest(array['id','professional_id','client_id','client_name','client_phone','client_cedula','client_email','public_code','quote_number','project_id','proposal_id','title','items','tax_mode','subtotal','tax_amount','total','notes','valid_until','status','accepted_at','declined_at','created_at','updated_at','professional_name','professional_full_name'])k$$;
create or replace function public.pro_manual_lead_quote_context(p_actor uuid,p_lead uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare l pro_lead_center_records;c pro_clients;begin
 perform pro_request_pipeline_owner(p_actor);select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=p_lead;if not found then raise exception 'Opportunity unavailable' using errcode='P0002';end if;if l.archived then raise exception 'Restore the opportunity before creating a quote' using errcode='40001';end if;
 select * into c from pro_clients where user_id=p_actor and id=l.client_id;if not found or c.archived then raise exception 'Choose an active private customer' using errcode='40001';end if;
 return jsonb_build_object('source',jsonb_build_object('leadId',l.id,'leadRevision',l.revision,'clientId',l.client_id),'client',jsonb_build_object('id',c.id,'name',c.name,'email',c.email,'phone',c.phone,'identification',c.identification,'address',c.address,'tradeName',c."tradeName"),'title',l.title,'currency','CRC');end $$;
create or replace function public.pro_manual_lead_quote_authorize(p_actor uuid,p_action uuid) returns void language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_manual_lead_quotes;begin
 perform pro_request_pipeline_owner(p_actor);select * into r from pro_manual_lead_quotes where owner_id=p_actor and action_id=p_action;if not found then raise exception 'Origin receipt unavailable' using errcode='42501';end if;
 if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=r.lead_id) or not exists(select 1 from quotes q join professionals p on p.id=q.professional_id and p.profile_id=p_actor join pro_quote_links l on l.user_id=p_actor and l."quoteId"=q.id::text and l."clientId"=r.source_client_id where q.id=r.quote_id and q.client_id is null and q.project_id is null and q.proposal_id is null) then raise exception 'Origin ownership unavailable' using errcode='42501';end if;end $$;
create or replace function public.pro_manual_lead_quote_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_manual_lead_quotes;begin
 perform pro_request_pipeline_owner(p_actor);select * into r from pro_manual_lead_quotes where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_manual_lead_quote_authorize(p_actor,p_action);return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_manual_lead_quote_create(p_actor uuid,p_input jsonb,p_source jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;lid uuid;l pro_lead_center_records;c pro_clients;r pro_manual_lead_quotes;old_input jsonb;old_result jsonb;answer jsonb;doc jsonb;begin
 perform pro_request_pipeline_owner(p_actor);
 if jsonb_typeof(p_input) is distinct from 'object' or p_input->>'context' is distinct from 'direct' or p_input?'projectId' or jsonb_typeof(p_input->'sourceManualLeadId') is distinct from 'string' or jsonb_typeof(p_input->'sourceManualLeadRevision') is distinct from 'number' or not coalesce(p_input->>'sourceManualLeadRevision'~'^[0-9]{1,10}$',false) or(p_input->>'sourceManualLeadRevision')::numeric not between 1 and 2147483647 or jsonb_typeof(p_input->'clientActionId') is distinct from 'string' or jsonb_typeof(p_input->'proClientId') is distinct from 'string' then raise exception 'Invalid manual opportunity quotation context' using errcode='22023';end if;
 aid:=(p_input->>'clientActionId')::uuid;lid:=(p_input->>'sourceManualLeadId')::uuid;if aid is null or lid is null then raise exception 'Invalid quotation identity' using errcode='22023';end if;
 -- Same global owner lock as old direct-quote and customer writers, acquired
 -- before catalogue/manual rows; the original creator reacquires it reentrantly.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-manual-lead-quote-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pro_request_pipeline_owner(p_actor);
 select * into r from pro_manual_lead_quotes where owner_id=p_actor and action_id=aid;if found then perform pro_manual_lead_quote_authorize(p_actor,aid);if r.input is distinct from p_input then raise exception 'Quotation action reused' using errcode='22023';end if;return r.result;end if;
 -- A pre-existing direct quotation is not evidence of this opportunity's intent.
 if exists(select 1 from pro_direct_project_quote_actions where actor_id=p_actor and action_id=aid) then raise exception 'Existing quote action has no manual-opportunity origin' using errcode='40001';end if;
 select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=lid for update;if not found then raise exception 'Opportunity unavailable' using errcode='42501';end if;if l.archived or l.revision<>(p_input->>'sourceManualLeadRevision')::integer or l.client_id<>p_input->>'proClientId' then raise exception 'Opportunity or customer changed' using errcode='40001';end if;
 select * into c from pro_clients where user_id=p_actor and id=l.client_id for update;if not found or c.archived then raise exception 'Choose an active private customer' using errcode='40001';end if;perform pro_request_pipeline_owner(p_actor);
 old_input:=p_input-array['sourceManualLeadId','sourceManualLeadRevision'];old_result:=pro_direct_project_quote_create(p_actor,old_input,p_source);perform pro_request_pipeline_owner(p_actor);doc:=pro_manual_lead_quote_dto(old_result->'quote');
 answer:=jsonb_build_object('link',jsonb_build_object('leadId',l.id,'sourceLeadRevision',l.revision,'sourceClientId',l.client_id,'quoteId',doc->'id','createdAt',now()),'quote',doc);
 insert into pro_manual_lead_quotes(owner_id,action_id,lead_id,source_lead_revision,source_client_id,source_snapshot,quote_id,input,result,actor_name)values(p_actor,aid,l.id,l.revision,l.client_id,pro_lead_center_manual_json(l),(doc->>'id')::uuid,p_input,answer,pro_team_name(p_actor));perform pro_manual_lead_quote_authorize(p_actor,aid);return answer;end $$;
create or replace function public.pro_manual_lead_quote_list(p_actor uuid,p_lead uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare anchor_time timestamptz;items jsonb;cursor_id uuid;begin
 perform pro_request_pipeline_owner(p_actor);if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=p_lead) then raise exception 'Opportunity unavailable' using errcode='P0002';end if;
 if p_after is not null then select r.created_at into anchor_time from pro_manual_lead_quotes r join quotes q on q.id=r.quote_id and q.deleted_at is null join professionals p on p.id=q.professional_id and p.profile_id=p_actor where r.owner_id=p_actor and r.lead_id=p_lead and r.quote_id=p_after;if not found then raise exception 'Quotation cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('link',r.result->'link','quote',pro_manual_lead_quote_dto(to_jsonb(q)||jsonb_build_object('professional_name',r.result->'quote'->'professional_name','professional_full_name',r.result->'quote'->'professional_full_name')))order by r.created_at desc,r.quote_id desc),'[]'::jsonb)into items from(select l.* from pro_manual_lead_quotes l join quotes d on d.id=l.quote_id and d.deleted_at is null join professionals p on p.id=d.professional_id and p.profile_id=p_actor where l.owner_id=p_actor and l.lead_id=p_lead and(p_after is null or(l.created_at,l.quote_id)<(anchor_time,p_after))order by l.created_at desc,l.quote_id desc limit 21)r join quotes q on q.id=r.quote_id;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->'quote'->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_manual_lead_quote_guard() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if exists(select 1 from pro_manual_lead_quotes where quote_id=old.id) and(new.professional_id is distinct from old.professional_id or new.client_id is distinct from old.client_id or new.project_id is distinct from old.project_id or new.proposal_id is distinct from old.proposal_id or new.id is distinct from old.id) then raise exception 'Manual opportunity quote identity is immutable' using errcode='23514';end if;return new;end $$;
drop trigger if exists pro_manual_lead_quote_guard on public.quotes;
create trigger pro_manual_lead_quote_guard before update on public.quotes for each row execute function pro_manual_lead_quote_guard();
create or replace function public.pro_manual_lead_quote_contact_guard() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if exists(select 1 from pro_manual_lead_quotes where owner_id=old.user_id and quote_id_text=old."quoteId") and(new.user_id is distinct from old.user_id or new."quoteId" is distinct from old."quoteId" or new."clientId" is distinct from old."clientId") then raise exception 'Manual opportunity quote customer is immutable' using errcode='23514';end if;return new;end $$;
drop trigger if exists pro_manual_lead_quote_contact_guard on public.pro_quote_links;
create trigger pro_manual_lead_quote_contact_guard before update on public.pro_quote_links for each row execute function pro_manual_lead_quote_contact_guard();
create or replace function public.pro_manual_lead_quote_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin raise exception 'Immutable manual opportunity quote origin' using errcode='23514';end $$;
drop trigger if exists pro_manual_lead_quote_immutable on public.pro_manual_lead_quotes;
create trigger pro_manual_lead_quote_immutable before update on public.pro_manual_lead_quotes for each row execute function pro_manual_lead_quote_immutable();
alter table public.pro_manual_lead_quotes enable row level security;
revoke all on public.pro_manual_lead_quotes from public,anon,authenticated;grant all on public.pro_manual_lead_quotes to service_role;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro_manual_lead_quote_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst, 'reload schema';

-- ===== manual-lead-work-local.sql =====
-- LOCAL PRO ONLY. Explicit private opportunity -> unscheduled private work.
-- No appointments, quotes, acceptance, payments, delivery or commercial-stage changes.
begin;
create table if not exists public.pro_manual_lead_works(
 owner_id uuid not null references profiles(id) on delete cascade,
 action_id uuid not null,lead_kind text not null default 'manual' check(lead_kind='manual'),lead_id uuid not null,
 source_lead_revision integer not null check(source_lead_revision>0),source_client_id text not null,source_snapshot jsonb not null,
 work_id uuid not null,work_id_text text generated always as(work_id::text)stored,
 input jsonb not null,result jsonb not null,actor_name text not null,created_at timestamptz not null default now(),
 primary key(owner_id,action_id),unique(owner_id,lead_id),unique(owner_id,work_id),
 foreign key(owner_id,lead_kind,lead_id)references pro_lead_center_records(owner_id,kind,id)on delete cascade,
 foreign key(owner_id,work_id_text)references pro_work(user_id,id)deferrable initially deferred
);
create or replace function public.pro_manual_lead_work_authorize(p_actor uuid,p_action uuid) returns void language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_manual_lead_works;begin
 perform pro_request_pipeline_owner(p_actor);select * into r from pro_manual_lead_works where owner_id=p_actor and action_id=p_action;if not found then raise exception 'Conversion unavailable' using errcode='42501';end if;
 if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=r.lead_id)or not exists(select 1 from pro_work where user_id=p_actor and id=r.work_id_text and "clientId"=r.source_client_id and "bookingClientId"is null)then raise exception 'Conversion ownership unavailable' using errcode='42501';end if;end $$;
create or replace function public.pro_manual_lead_work_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_manual_lead_works;begin
 perform pro_request_pipeline_owner(p_actor);select * into r from pro_manual_lead_works where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_manual_lead_work_authorize(p_actor,p_action);return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_manual_lead_work_mapping_read(p_actor uuid,p_lead uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_manual_lead_works;begin
 perform pro_request_pipeline_owner(p_actor);if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=p_lead)then raise exception 'Opportunity unavailable' using errcode='P0002';end if;
 select * into r from pro_manual_lead_works where owner_id=p_actor and lead_id=p_lead;if not found then return jsonb_build_object('mapping',null);end if;perform pro_manual_lead_work_authorize(p_actor,r.action_id);return jsonb_build_object('mapping',r.result);end $$;
create or replace function public.pro_manual_lead_work_context(p_actor uuid,p_lead uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare l pro_lead_center_records;c pro_clients;m jsonb;begin
 perform pro_request_pipeline_owner(p_actor);select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=p_lead;if not found then raise exception 'Opportunity unavailable' using errcode='P0002';end if;
 m:=pro_manual_lead_work_mapping_read(p_actor,p_lead)->'mapping';select * into c from pro_clients where user_id=p_actor and id=l.client_id;
 if not found then raise exception 'Private customer unavailable' using errcode='42501';end if;
 if m='null'::jsonb and(l.archived or c.archived)then raise exception 'Restore the opportunity and customer before converting' using errcode='40001';end if;
 return jsonb_build_object('source',jsonb_build_object('leadId',l.id,'leadRevision',l.revision,'clientId',l.client_id),'client',jsonb_build_object('id',c.id,'name',c.name,'archived',c.archived),'service',l.title,'mapping',m);end $$;
create or replace function public.pro_manual_lead_work_convert(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;lid uuid;wid uuid;rev integer;l pro_lead_center_records;c pro_clients;r pro_manual_lead_works;v integer;w jsonb;answer jsonb;begin
 perform pro_request_pipeline_owner(p_actor);
 if jsonb_typeof(p_input)is distinct from'object'or not(p_input?&array['action','actionId','leadId','leadRevision','workId'])or exists(select 1 from jsonb_object_keys(p_input)k where k<>all(array['action','actionId','leadId','leadRevision','workId']))or p_input->>'action'is distinct from'convert'or jsonb_typeof(p_input->'actionId')is distinct from'string'or jsonb_typeof(p_input->'leadId')is distinct from'string'or jsonb_typeof(p_input->'workId')is distinct from'string'or jsonb_typeof(p_input->'leadRevision')is distinct from'number'or not coalesce(p_input->>'leadRevision'~'^[0-9]{1,10}$',false)or(p_input->>'leadRevision')::numeric not between 1 and 2147483647 then raise exception 'Invalid conversion' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;lid:=(p_input->>'leadId')::uuid;wid:=(p_input->>'workId')::uuid;rev:=(p_input->>'leadRevision')::integer;
 -- Reentrant old core/customer owner lock precedes catalogue/source rows.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-manual-lead-work-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pro_request_pipeline_owner(p_actor);
 select * into r from pro_manual_lead_works where owner_id=p_actor and action_id=aid;if found then perform pro_manual_lead_work_authorize(p_actor,aid);if r.input is distinct from p_input then raise exception 'Conversion action reused' using errcode='22023';end if;return r.result;end if;
 select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=lid for update;if not found then raise exception 'Opportunity unavailable' using errcode='42501';end if;
 if exists(select 1 from pro_manual_lead_works where owner_id=p_actor and lead_id=lid)then raise exception 'Opportunity already converted' using errcode='40001';end if;
 if l.archived or l.revision<>rev then raise exception 'Opportunity changed' using errcode='40001';end if;
 if exists(select 1 from pro_work where user_id=p_actor and id=wid::text)then raise exception 'Work identity already exists' using errcode='40001';end if;
 select * into c from pro_clients where user_id=p_actor and id=l.client_id for update;if not found or c.archived then raise exception 'Choose an active private customer' using errcode='40001';end if;perform pro_request_pipeline_owner(p_actor);
 select revision into v from pro_workspace_core where user_id=p_actor for update;if coalesce(v,0)>=2147483647 then raise exception 'Workspace revision exhausted' using errcode='40001';end if;
 w:=jsonb_build_object('id',wid,'client',c.name,'service',l.title,'stage','new','start','','end','','clientId',c.id,'cancelled',false);
 perform pro_patch_core(p_actor,'work',w,coalesce(v,0));perform pro_request_pipeline_owner(p_actor);
 answer:=jsonb_build_object('action','convert','link',jsonb_build_object('leadId',lid,'sourceLeadRevision',rev,'sourceClientId',c.id,'workId',wid,'createdAt',now()),'work',w);
 insert into pro_manual_lead_works(owner_id,action_id,lead_id,source_lead_revision,source_client_id,source_snapshot,work_id,input,result,actor_name)values(p_actor,aid,lid,rev,c.id,pro_lead_center_manual_json(l),wid,p_input,answer,pro_team_name(p_actor));perform pro_manual_lead_work_authorize(p_actor,aid);return answer;end $$;
create or replace function public.pro_manual_lead_work_guard()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if exists(select 1 from pro_manual_lead_works where owner_id=old.user_id and work_id_text=old.id)and(new.user_id is distinct from old.user_id or new.id is distinct from old.id or new."clientId"is distinct from old."clientId"or new."bookingClientId"is distinct from old."bookingClientId")then raise exception 'Converted work identity is immutable' using errcode='23514';end if;return new;end $$;
drop trigger if exists pro_manual_lead_work_guard on public.pro_work;
create trigger pro_manual_lead_work_guard before update on public.pro_work for each row execute function pro_manual_lead_work_guard();
create or replace function public.pro_manual_lead_work_immutable()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin raise exception 'Immutable opportunity conversion'using errcode='23514';end $$;
drop trigger if exists pro_manual_lead_work_immutable on public.pro_manual_lead_works;
create trigger pro_manual_lead_work_immutable before update on public.pro_manual_lead_works for each row execute function pro_manual_lead_work_immutable();
alter table public.pro_manual_lead_works enable row level security;
revoke all on public.pro_manual_lead_works from public,anon,authenticated;grant all on public.pro_manual_lead_works to service_role;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname like'pro_manual_lead_work_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst,'reload schema';

-- ===== client-pending-work-local.sql =====
-- LOCAL PRO ONLY. Additive corrected pending-work reader; original function untouched.
-- Undated new/quoting work needs planning, never an expired-appointment warning.
begin;
create or replace function public.pro_client_pending_work_page(p_user uuid,p_client text,p_after jsonb default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare moment timestamptz:=statement_timestamp(); result jsonb;
begin
 -- Single Pro entitlement rule (pro_entitled): hasProAccess plus the ban check, including private Pro
 -- providers without a public directory row. Admin MFA is checked by the HTTP boundary; service-role only.
 perform public.pro_entitled_require(p_user);
 if p_client is null or length(p_client) not between 1 and 160 then raise exception 'Invalid client' using errcode='22023'; end if;
 if p_after is not null then
  if jsonb_typeof(p_after)<>'object' or not(p_after ?& array['priority','at','key','asOf'])
    or jsonb_typeof(p_after->'priority')<>'number' or (p_after->>'priority') !~ '^[0-4]$'
    or jsonb_typeof(p_after->'at')<>'string' or length(p_after->>'at')>40
    or jsonb_typeof(p_after->'key')<>'string' or length(p_after->>'key') not between 1 and 180
    or jsonb_typeof(p_after->'asOf')<>'string' or length(p_after->>'asOf')>40 or pro_instant(p_after->>'asOf') is null
  then raise exception 'Invalid cursor' using errcode='22023'; end if;
  moment:=pro_instant(p_after->>'asOf');
 end if;
 if not exists(select 1 from pro_clients where user_id=p_user and id=p_client) then return null; end if;
 with candidates as (
  select w.id,'work:'||w.id as key,'work'::text as kind,w.service as title,
   case when w.stage in('new','quoting') and w.start='' and w."end"='' then 'plan' when pro_instant(w."end") is null or pro_instant(w."end")<=moment then 'review' else 'upcoming' end as reason,
   coalesce(to_char(pro_instant(w.start) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'') as at,false as legacy,
   case when w.stage in('new','quoting') and w.start='' and w."end"='' then 1 when pro_instant(w."end") is null or pro_instant(w."end")<=moment then 0 else 1 end as priority,null::integer as "sourceRevision",null::text as "requestStatus"
  from pro_work w where w.user_id=p_user and w."clientId"=p_client and not w.cancelled and w.stage<>'completed'
  union all
  select q.id::text,'standard:'||q.id::text,'quote',coalesce(q.title,''),
   case when q.status='accepted' then 'schedule' when q.status='draft' then 'prepare' when q.valid_until<(moment at time zone 'America/Costa_Rica')::date then 'expired' else 'response' end,
   to_char(q.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),false,
   case when q.status='accepted' then 2 when q.status='draft' or q.valid_until<(moment at time zone 'America/Costa_Rica')::date then 3 else 4 end,null::integer,null::text
  from pro_quote_links l join quotes q on q.id::text=l."quoteId"
   join professionals p on p.id=q.professional_id and p.profile_id=p_user
  where l.user_id=p_user and l."clientId"=p_client and q.deleted_at is null and q.status in ('draft','sent','accepted')
   and (q.status<>'accepted' or not exists(select 1 from pro_work w where w.user_id=p_user and w."externalQuoteId"=q.id::text and not w.cancelled))
  union all
  select q.id,'legacy:'||q.id,'quote',q.title,case q.status when 'accepted' then 'schedule' else 'prepare' end,'',true,case q.status when 'accepted' then 2 else 3 end,null::integer,null::text
  from pro_legacy_quotes q where q.user_id=p_user and q."clientId"=p_client and q.status in ('draft','accepted')
   and (q.status<>'accepted' or not exists(select 1 from pro_work w where w.user_id=p_user and w."quoteId"=q.id and not w.cancelled))
  union all
  select r.id::text,'request:'||r.id::text,'request',r.service,
   case when r.status='requested' then 'request' else 'confirmation' end,
   coalesce(to_char((case when r.status='proposed' then r.proposed_start else r.requested_start end) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),''),false,
   case when r.status='requested' then 0 else 4 end,r.revision,r.status
  from pro_appointment_requests r
  where r.owner_id=p_user and p_client='reservation-'||r.client_user_id::text
   and r.status in ('requested','proposed') and r.work_id is null
 ), page as (
  select * from candidates where p_after is null or (priority,at,key)>((p_after->>'priority')::integer,p_after->>'at',p_after->>'key') order by priority,at,key limit 7
 )
 select jsonb_build_object('asOf',moment,'fingerprint',(select md5(coalesce(jsonb_agg(to_jsonb(c) order by priority,at,key)::text,'[]')) from candidates c),
  'summary',(select jsonb_build_object('plan',count(*) filter(where reason='plan'),'review',count(*) filter(where reason='review'),'upcoming',count(*) filter(where reason='upcoming'),'prepare',count(*) filter(where reason='prepare'),'response',count(*) filter(where reason='response'),'schedule',count(*) filter(where reason='schedule'),'request',count(*) filter(where reason='request'),'confirmation',count(*) filter(where reason='confirmation'),'expired',count(*) filter(where reason='expired')) from candidates),
  'items',coalesce((select jsonb_agg(to_jsonb(r) order by priority,at,key) from(select * from page order by priority,at,key limit 6) r),'[]'),
  'nextCursor',case when(select count(*) from page)>6 then(select jsonb_build_object('priority',priority,'at',at,'key',key,'asOf',moment) from page order by priority,at,key offset 5 limit 1) else null end) into result;
 return result;
end;$$;
revoke all on function public.pro_client_pending_work_page(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.pro_client_pending_work_page(uuid,text,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== lead-followups-local.sql =====
-- LOCAL PRO ONLY. Manual-opportunity follow-up + mixed read-only next contacts.
-- Existing request follow-ups and their exact receipts are never rewritten.
begin;
create table if not exists public.pro_lead_followups(owner_id uuid not null,lead_kind text not null default'manual'check(lead_kind='manual'),lead_id uuid not null,due_date date check(due_date between date'1900-01-01'and date'2100-12-31'),note text not null default''check(length(note)<=1000),status text not null default'open'check(status in('open','done')),revision integer not null check(revision>0),updated_at timestamptz not null default now(),primary key(owner_id,lead_id),foreign key(owner_id,lead_kind,lead_id)references pro_lead_center_records(owner_id,kind,id)on delete cascade);
create index if not exists pro_lead_followups_due on pro_lead_followups(owner_id,due_date,lead_id)where status='open'and due_date is not null;
create table if not exists public.pro_lead_followup_history(owner_id uuid not null,lead_id uuid not null,action_id uuid not null,action text not null check(action in('save','complete','reopen')),before_followup jsonb,after_followup jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id),foreign key(owner_id,lead_id)references pro_lead_followups(owner_id,lead_id)on delete cascade);
create index if not exists pro_lead_followup_history_page on pro_lead_followup_history(owner_id,lead_id,((after_followup->>'revision')::integer)desc);
create table if not exists public.pro_lead_followup_actions(owner_id uuid not null,action_id uuid not null,lead_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id),foreign key(owner_id,lead_id)references pro_lead_followups(owner_id,lead_id)on delete cascade);
create or replace function public.pro_lead_followup_owner(p_actor uuid)returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$begin
 -- Single Pro entitlement rule (pro_entitled, pro-entitled-draft.sql): hasProAccess plus the ban check.
 -- No public-directory/profile prerequisite.
 -- The service-only HTTP boundary separately checks admin MFA.
 perform public.pro_entitled_require(p_actor);end $$;
create or replace function public.pro_lead_followup_json(p_row pro_lead_followups,p_lead uuid)returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('leadId',p_lead,'dueDate',case when p_row.due_date is null then null else to_char(p_row.due_date,'YYYY-MM-DD')end,'note',coalesce(p_row.note,''),'status',coalesce(p_row.status,'open'),'revision',coalesce(p_row.revision,0),'updatedAt',p_row.updated_at)$$;
create or replace function public.pro_lead_followup_history_read(p_actor uuid,p_lead uuid,p_after uuid default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare rev integer;items jsonb;cursor_id uuid;begin
 perform pro_lead_followup_owner(p_actor);if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=p_lead)then raise exception'Opportunity unavailable'using errcode='P0002';end if;
 if p_after is not null then select(after_followup->>'revision')::integer into rev from pro_lead_followup_history where owner_id=p_actor and lead_id=p_lead and action_id=p_after;if not found then raise exception'History cursor changed'using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(x.content order by x.revision desc),'[]')into items from(select(after_followup->>'revision')::integer revision,jsonb_build_object('actionId',action_id,'action',action,'at',at,'before',before_followup,'after',after_followup)content from pro_lead_followup_history where owner_id=p_actor and lead_id=p_lead and(p_after is null or(after_followup->>'revision')::integer<rev)order by(after_followup->>'revision')::integer desc limit 21)x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'actionId')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_lead_followup_read(p_actor uuid,p_lead uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare f pro_lead_followups;h jsonb;archived boolean;begin
 perform pro_lead_followup_owner(p_actor);select l.archived into archived from pro_lead_center_records l where owner_id=p_actor and kind='manual'and id=p_lead;if not found then raise exception'Opportunity unavailable'using errcode='P0002';end if;
 select * into f from pro_lead_followups where owner_id=p_actor and lead_id=p_lead;h:=pro_lead_followup_history_read(p_actor,p_lead);return jsonb_build_object('followup',pro_lead_followup_json(f,p_lead),'canWrite',not archived and exists(select 1 from pro_clients c join pro_lead_center_records l on l.owner_id=c.user_id and l.client_id=c.id and l.kind='manual'where l.owner_id=p_actor and l.id=p_lead and not c.archived),'history',h->'items','nextCursor',h->'nextCursor');end $$;
create or replace function public.pro_lead_followup_action_read(p_actor uuid,p_action uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_followup_actions;begin
 perform pro_lead_followup_owner(p_actor);select * into r from pro_lead_followup_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=r.lead_id)then raise exception'Opportunity unavailable'using errcode='42501';end if;return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_lead_followup_mutate(p_actor uuid,p_input jsonb)returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare lid uuid;aid uuid;act text;rev integer;f pro_lead_followups;r pro_lead_followup_actions;before_json jsonb;after_json jsonb;answer jsonb;due date;n text;archived boolean;has_followup boolean;client_archived boolean;begin
 perform pro_lead_followup_owner(p_actor);if jsonb_typeof(p_input)is distinct from'object'or not(p_input?&array['action','actionId','leadId','revision'])or jsonb_typeof(p_input->'action')is distinct from'string'or jsonb_typeof(p_input->'actionId')is distinct from'string'or jsonb_typeof(p_input->'leadId')is distinct from'string'or jsonb_typeof(p_input->'revision')is distinct from'number'or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false)or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception'Invalid follow-up'using errcode='22023';end if;
 act:=p_input->>'action';lid:=(p_input->>'leadId')::uuid;aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 if act='save'then
 if not(p_input?&array['dueDate','note'])or exists(select 1 from jsonb_object_keys(p_input)k where k<>all(array['action','actionId','leadId','revision','dueDate','note']))or jsonb_typeof(p_input->'note')is distinct from'string'or jsonb_typeof(p_input->'dueDate')not in('null','string')then raise exception'Invalid follow-up fields'using errcode='22023';end if;
 n:=btrim(p_input->>'note');if length(n)>1000 then raise exception'Invalid note'using errcode='22023';end if;
 if p_input->'dueDate'<>'null'::jsonb then if not coalesce(p_input->>'dueDate'~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false)then raise exception'Invalid date'using errcode='22023';end if;due:=(p_input->>'dueDate')::date;if due not between date'1900-01-01'and date'2100-12-31'or to_char(due,'YYYY-MM-DD')<>p_input->>'dueDate'then raise exception'Invalid date'using errcode='22023';end if;end if;
 elsif act in('complete','reopen')then if rev=0 or exists(select 1 from jsonb_object_keys(p_input)k where k<>all(array['action','actionId','leadId','revision']))then raise exception'Invalid follow-up action'using errcode='22023';end if;
 else raise exception'Invalid action'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-followup-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-followup:'||p_actor::text||':'||lid::text,0));
 select l.archived into archived from pro_lead_center_records l where owner_id=p_actor and kind='manual'and id=lid for update;if not found then raise exception'Opportunity unavailable'using errcode='42501';end if;perform pro_lead_followup_owner(p_actor);
 select * into r from pro_lead_followup_actions where owner_id=p_actor and action_id=aid;if found then if r.input is distinct from p_input then raise exception'Action identity reused'using errcode='22023';end if;return r.result;end if;
 select c.archived into client_archived from pro_clients c join pro_lead_center_records l on l.owner_id=c.user_id and l.client_id=c.id and l.kind='manual'where l.owner_id=p_actor and l.id=lid for update of c;perform pro_lead_followup_owner(p_actor);
 if archived or coalesce(client_archived,true)then raise exception'Restore the opportunity before editing its follow-up'using errcode='40001';end if;
 select * into f from pro_lead_followups where owner_id=p_actor and lead_id=lid for update;has_followup:=found;perform pro_lead_followup_owner(p_actor);
 if not has_followup then if act<>'save'or rev<>0 then raise exception'Follow-up changed'using errcode='40001';end if;insert into pro_lead_followups(owner_id,lead_id,due_date,note,status,revision)values(p_actor,lid,due,n,'open',1)returning*into f;
 else
 if rev<>f.revision then raise exception'Follow-up changed'using errcode='40001';end if;before_json:=pro_lead_followup_json(f,lid);
 if act='save'then update pro_lead_followups set due_date=due,note=n,revision=revision+1,updated_at=now()where owner_id=p_actor and lead_id=lid returning*into f;
 else if(act='complete'and f.status<>'open')or(act='reopen'and f.status<>'done')then raise exception'Invalid transition'using errcode='22023';end if;update pro_lead_followups set status=case when act='complete'then'done'else'open'end,revision=revision+1,updated_at=now()where owner_id=p_actor and lead_id=lid returning*into f;end if;end if;
 after_json:=pro_lead_followup_json(f,lid);answer:=jsonb_build_object('followup',after_json);insert into pro_lead_followup_history(owner_id,lead_id,action_id,action,before_followup,after_followup)values(p_actor,lid,aid,act,before_json,after_json);insert into pro_lead_followup_actions(owner_id,action_id,lead_id,input,result)values(p_actor,aid,lid,p_input,answer);perform pro_lead_followup_owner(p_actor);return answer;end $$;
create or replace function public.pro_lead_followups_upcoming(p_actor uuid,p_after text default null,p_snapshot text default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare answer jsonb;begin
 perform pro_lead_followup_owner(p_actor);if(p_after is null)<>(p_snapshot is null)or(p_snapshot is not null and p_snapshot!~'^[0-9a-f]{32}$')then raise exception'Invalid pagination snapshot'using errcode='22023';end if;if p_after is not null and p_after!~'^(manual|request):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'then raise exception'Invalid cursor'using errcode='22023';end if;
 with candidates as(
 select'manual'::text kind,f.lead_id id,f.due_date,f.note,f.status,f.revision,f.updated_at,l.title,c.name client_name from pro_lead_followups f join pro_lead_center_records l on l.owner_id=f.owner_id and l.kind='manual'and l.id=f.lead_id and not l.archived join pro_clients c on c.user_id=l.owner_id and c.id=l.client_id and not c.archived where f.owner_id=p_actor and f.status='open'and f.due_date is not null
 union all
 select'request',f.request_id,f.due_date,f.note,f.status,f.revision,f.updated_at,r.service,r.client_name from pro_request_followups f join pro_appointment_requests r on r.owner_id=f.owner_id and r.id=f.request_id left join pro_lead_center_records pref on pref.owner_id=f.owner_id and pref.kind='request'and pref.id=f.request_id where f.owner_id=p_actor and f.status='open'and f.due_date is not null and not coalesce(pref.archived,false)and not exists(select 1 from pro_clients c where c.user_id=p_actor and c.id='reservation-'||r.client_user_id::text and c.archived)
 ),metadata as(select md5(p_actor::text||(statement_timestamp()at time zone'America/Costa_Rica')::date::text||coalesce(jsonb_agg(jsonb_build_array(kind,id,due_date,revision,updated_at,title,client_name)order by due_date,kind,id)::text,'[]'))fingerprint from candidates),anchor as(select due_date,kind,id from candidates where kind||':'||id::text=p_after),page as(
 select c.* from candidates c where p_after is null or(c.due_date,c.kind,c.id)>(select a.due_date,a.kind,a.id from anchor a)order by c.due_date,c.kind,c.id limit 21
 ),encoded as(select kind,id,due_date,jsonb_build_object('kind',kind,'id',id,'dueDate',to_char(due_date,'YYYY-MM-DD'),'note',note,'status',status,'revision',revision,'updatedAt',updated_at,'title',title,'clientName',client_name)content from page)
 select jsonb_build_object('fingerprint',(select fingerprint from metadata),'asOfDayCR',to_char((statement_timestamp()at time zone'America/Costa_Rica')::date,'YYYY-MM-DD'),'summary',(select jsonb_build_object('open',count(*),'overdue',count(*)filter(where due_date<(statement_timestamp()at time zone'America/Costa_Rica')::date),'today',count(*)filter(where due_date=(statement_timestamp()at time zone'America/Costa_Rica')::date))from candidates),'items',coalesce((select jsonb_agg(content order by due_date,kind,id)from(select*from encoded order by due_date,kind,id limit 20)e),'[]'::jsonb),'nextCursor',case when(select count(*)from page)>20 then(select kind||':'||id::text from page order by due_date,kind,id offset 19 limit 1)else null end,'validCursor',p_after is null or exists(select 1 from anchor))into answer;
 if p_snapshot is not null and p_snapshot is distinct from answer->>'fingerprint'then raise exception'Follow-up snapshot changed'using errcode='40001';end if;if not(answer->>'validCursor')::boolean then raise exception'Follow-up cursor changed'using errcode='40001';end if;return answer-'validCursor';end $$;
create or replace function public.pro_lead_followup_immutable()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin raise exception'Immutable follow-up audit'using errcode='23514';end $$;
drop trigger if exists pro_lead_followup_history_immutable on pro_lead_followup_history;
create trigger pro_lead_followup_history_immutable before update on pro_lead_followup_history for each row execute function pro_lead_followup_immutable();
drop trigger if exists pro_lead_followup_action_immutable on pro_lead_followup_actions;
create trigger pro_lead_followup_action_immutable before update on pro_lead_followup_actions for each row execute function pro_lead_followup_immutable();
alter table pro_lead_followups enable row level security;alter table pro_lead_followup_history enable row level security;alter table pro_lead_followup_actions enable row level security;
revoke all on pro_lead_followups,pro_lead_followup_history,pro_lead_followup_actions from public,anon,authenticated;grant all on pro_lead_followups,pro_lead_followup_history,pro_lead_followup_actions to service_role;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and(p.proname like'pro_lead_followup_%'or p.proname='pro_lead_followups_upcoming')loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst,'reload schema';

-- ===== lead-origins-local.sql =====
-- LOCAL PRO ONLY. Private commercial attribution. Never rewrites legacy sourceLabel,
-- entry kind, appointments, stages, forecasts, messages or access permissions.
begin;
create table if not exists pro_lead_origin_channels(owner_id uuid not null references profiles(id)on delete cascade,id text not null,name_override text check(length(btrim(name_override))between 1 and 80 and name_override!~'[[:cntrl:]]'),archived boolean not null default false,revision integer not null check(revision>=0),created_at timestamptz,updated_at timestamptz,primary key(owner_id,id),check(id in('direct','referral','website','social','advertising','other')or(id~'^[a-f0-9-]{36}$'and name_override is not null)),check((revision=0 and not archived and id in('direct','referral','website','social','advertising','other')and name_override is null and created_at is null and updated_at is null)or(revision>0 and created_at is not null and updated_at is not null)));
create table if not exists pro_lead_origin_assignments(owner_id uuid not null references profiles(id)on delete cascade,kind text not null check(kind in('manual','request')),id uuid not null,manual_id uuid,manual_kind text not null default'manual'check(manual_kind='manual'),request_id uuid,channel_id text check(channel_id in('direct','referral','website','social','advertising','other')or channel_id~'^[a-f0-9-]{36}$'),custom_channel_id text generated always as(case when channel_id in('direct','referral','website','social','advertising','other')then null else channel_id end)stored,revision integer not null check(revision>0),updated_at timestamptz not null default now(),primary key(owner_id,kind,id),foreign key(owner_id,manual_kind,manual_id)references pro_lead_center_records(owner_id,kind,id)on delete cascade,foreign key(owner_id,request_id)references pro_appointment_requests(owner_id,id)on delete cascade,foreign key(owner_id,custom_channel_id)references pro_lead_origin_channels(owner_id,id),check((kind='manual'and manual_id is not null and manual_id=id and request_id is null)or(kind='request'and request_id is not null and request_id=id and manual_id is null)));
create index if not exists pro_lead_origin_channel_refs on pro_lead_origin_assignments(owner_id,channel_id,kind,id);
create table if not exists pro_lead_origin_actions(owner_id uuid not null references profiles(id)on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id));
create table if not exists pro_lead_origin_history(owner_id uuid not null,kind text not null,id uuid not null,action_id uuid not null,action text not null check(action in('assign','clear')),before_origin jsonb not null,after_origin jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id),foreign key(owner_id,kind,id)references pro_lead_origin_assignments(owner_id,kind,id)on delete cascade);
create index if not exists pro_lead_origin_history_page on pro_lead_origin_history(owner_id,kind,id,((after_origin->>'revision')::integer)desc);
create or replace function public.pro_lead_origin_owner(p_actor uuid)returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$begin
 -- Single Pro entitlement rule (pro_entitled, pro-entitled-draft.sql): hasProAccess plus the ban check.
 -- No public-directory/profile prerequisite.
 -- The service-only HTTP boundary separately checks admin MFA.
 perform public.pro_entitled_require(p_actor);end $$;
create or replace function public.pro_lead_origin_stage_catalog(p_actor uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare stages jsonb;begin perform pro_lead_origin_owner(p_actor);
 with defaults as(select v id,(n-1)::integer position from unnest(array['new','followed_up','connected','meeting_scheduled','estimate_sent','won']) with ordinality x(v,n)),all_stages as(select d.id,coalesce(s.position,d.position)position,s.name,coalesce(s.hidden,false)hidden,s.reassign_to_id,true builtin from defaults d left join pro_request_pipeline_stages s on s.owner_id=p_actor and s.id=d.id union all select id,position,name,hidden,reassign_to_id,false from pro_request_pipeline_stages where owner_id=p_actor and not retired and id not in('new','followed_up','connected','meeting_scheduled','estimate_sent','won')) select jsonb_agg(jsonb_build_object('id',id,'builtin',builtin,'name',name,'position',position,'hidden',hidden,'reassignToId',reassign_to_id) order by position) into stages from all_stages;
 return jsonb_build_object('revision',coalesce((select revision from pro_request_pipeline_heads where owner_id=p_actor),0),'stages',stages);end $$;
create or replace function public.pro_lead_origin_request(p_actor uuid,p_request uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_appointment_requests;state jsonb;automatic jsonb;record jsonb;effective text;followup pro_request_followups;begin
 perform pro_lead_origin_owner(p_actor);select * into r from pro_appointment_requests where owner_id=p_actor and id=p_request;if not found then raise exception 'Request unavailable' using errcode='P0002';end if;state:=pro_request_pipeline_state(p_actor,p_request);automatic:=pro_request_pipeline_auto(p_actor,p_request);record:=pro_appointment_record(p_actor,p_request);effective:=coalesce(state->>'stageId',automatic->>'stageId');select coalesce(reassign_to_id,effective) into effective from pro_request_pipeline_stages where owner_id=p_actor and id=effective;effective:=coalesce(effective,state->>'stageId',automatic->>'stageId');
 select * into followup from pro_request_followups where owner_id=p_actor and request_id=p_request;
 return jsonb_build_object('requestId',r.id,'position',r.position,'service',r.service,'clientName',r.client_name,'publicStatus',r.status,'requestRevision',r.revision,'createdAt',r.created_at,'updatedAt',r.updated_at,'start',record->'start','workId',r.work_id,'workCancelled',record->'workCancelled','state',state,'effectiveStageId',effective,'automaticStageId',automatic->'stageId','evidence',automatic->'evidence','followup',pro_request_followup_json(followup,r.id));end $$;
create or replace function public.pro_lead_origin_item(p_actor uuid,p_kind text,p_id uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_center_records;c pro_clients;begin
 perform pro_lead_origin_owner(p_actor);if p_kind is null or p_kind not in('manual','request') then raise exception 'Invalid lead source' using errcode='22023';end if;select * into r from pro_lead_center_records where owner_id=p_actor and kind=p_kind and id=p_id;
 if p_kind='manual' then if not found then raise exception 'Opportunity unavailable' using errcode='P0002';end if;select * into c from pro_clients where user_id=p_actor and id=r.client_id;return jsonb_build_object('kind','manual','id',r.id,'manual',pro_lead_center_manual_json(r),'client',jsonb_build_object('id',c.id,'name',c.name,'archived',c.archived));end if;
 if not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=p_id) then raise exception 'Request unavailable' using errcode='P0002';end if;return jsonb_build_object('kind','request','id',p_id,'request',pro_lead_origin_request(p_actor,p_id),'preference',jsonb_build_object('revision',coalesce(r.revision,0),'archived',coalesce(r.archived,false),'updatedAt',r.updated_at));end $$;
create or replace function public.pro_lead_origin_catalog(p_actor uuid)returns table(id text,name text,custom_name boolean,builtin boolean,archived boolean,revision integer,created_at timestamptz,updated_at timestamptz)language plpgsql stable security invoker set search_path=public,pg_temp as $$begin perform pro_lead_origin_owner(p_actor);return query
 with defaults(id,label)as(values('direct','Direct'),('referral','Referral'),('website','Website'),('social','Social media'),('advertising','Advertising'),('other','Other'))
 select d.id,coalesce(c.name_override,d.label),c.name_override is not null,true,coalesce(c.archived,false),coalesce(c.revision,0),c.created_at,c.updated_at from defaults d left join pro_lead_origin_channels c on c.owner_id=p_actor and c.id=d.id
 union all select c.id,c.name_override,true,false,c.archived,c.revision,c.created_at,c.updated_at from pro_lead_origin_channels c where c.owner_id=p_actor and c.id not in('direct','referral','website','social','advertising','other');end $$;
create or replace function public.pro_lead_origin_channel_json(p_actor uuid,p_id text)returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('id',c.id,'name',c.name,'customName',c.custom_name,'builtin',c.builtin,'archived',c.archived,'revision',c.revision,'createdAt',c.created_at,'updatedAt',c.updated_at)from pro_lead_origin_catalog(p_actor)c where c.id=p_id$$;
create or replace function public.pro_lead_origin_get(p_actor uuid,p_kind text,p_id uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare source jsonb;a pro_lead_origin_assignments;can_write boolean;begin
 perform pro_lead_origin_owner(p_actor);source:=pro_lead_origin_item(p_actor,p_kind,p_id);select*into a from pro_lead_origin_assignments where owner_id=p_actor and kind=p_kind and id=p_id;
 can_write:=case when p_kind='manual'then not(source->'manual'->>'archived')::boolean and not(source->'client'->>'archived')::boolean else not(source->'preference'->>'archived')::boolean and not exists(select 1 from pro_clients c join pro_appointment_requests r on r.owner_id=c.user_id and c.id='reservation-'||r.client_user_id::text where r.owner_id=p_actor and r.id=p_id and c.archived)end;
 return jsonb_build_object('kind',p_kind,'id',p_id,'entryKind',case when p_kind='manual'then'manual'else'contratacr'end,'channel',pro_lead_origin_channel_json(p_actor,a.channel_id),'legacyLabel',case when p_kind='manual'then source->'manual'->>'sourceLabel'else''end,'revision',coalesce(a.revision,0),'updatedAt',a.updated_at,'canWrite',can_write);end $$;
create or replace function public.pro_lead_origin_action_read(p_actor uuid,p_action uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_origin_actions;begin
 perform pro_lead_origin_owner(p_actor);select*into r from pro_lead_origin_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;if r.result->>'type'='origin'then perform pro_lead_origin_get(p_actor,r.input->>'kind',(r.input->>'id')::uuid);end if;return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_lead_origin_history_read(p_actor uuid,p_kind text,p_id uuid,p_after uuid default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare rev integer;items jsonb;cursor_id uuid;begin
 perform pro_lead_origin_get(p_actor,p_kind,p_id);if p_after is not null then select(after_origin->>'revision')::integer into rev from pro_lead_origin_history where owner_id=p_actor and kind=p_kind and id=p_id and action_id=p_after;if not found then raise exception'History cursor changed'using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(content order by revision desc),'[]')into items from(select(after_origin->>'revision')::integer revision,jsonb_build_object('actionId',action_id,'action',action,'at',at,'before',before_origin,'after',after_origin)content from pro_lead_origin_history where owner_id=p_actor and kind=p_kind and id=p_id and(p_after is null or(after_origin->>'revision')::integer<rev)order by(after_origin->>'revision')::integer desc limit 21)h;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'actionId')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_lead_origin_context(p_actor uuid,p_kind text,p_id uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare origin jsonb;h jsonb;begin origin:=pro_lead_origin_get(p_actor,p_kind,p_id);h:=pro_lead_origin_history_read(p_actor,p_kind,p_id);return jsonb_build_object('origin',origin,'history',h->'items','nextCursor',h->'nextCursor');end $$;
create or replace function public.pro_lead_origin_batch(p_actor uuid,p_refs jsonb)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r jsonb;items jsonb:='[]';seen text[]:=array[]::text[];k text;begin perform pro_lead_origin_owner(p_actor);if jsonb_typeof(p_refs)is distinct from'array'or jsonb_array_length(p_refs)>20 then raise exception'Invalid references'using errcode='22023';end if;
 for r in select value from jsonb_array_elements(p_refs)loop if jsonb_typeof(r)is distinct from'object'or not(r?&array['kind','id'])or exists(select 1 from jsonb_object_keys(r)key where key<>all(array['kind','id']))or r->>'kind'not in('manual','request')or jsonb_typeof(r->'id')is distinct from'string'then raise exception'Invalid reference'using errcode='22023';end if;k:=(r->>'kind')||':'||(r->>'id');if k=any(seen)then raise exception'Duplicate reference'using errcode='22023';end if;seen:=array_append(seen,k);items:=items||jsonb_build_array(pro_lead_origin_get(p_actor,r->>'kind',(r->>'id')::uuid));end loop;return jsonb_build_object('items',items);end $$;
create or replace function public.pro_lead_origin_channels_read(p_actor uuid,p_status text default'active',p_query text default'',p_after text default null,p_snapshot text default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare answer jsonb;begin
 perform pro_lead_origin_owner(p_actor);if p_status not in('active','archived')or p_status is null or p_query is null or length(p_query)>100 or(p_after is null)<>(p_snapshot is null)then raise exception'Invalid channel query'using errcode='22023';end if;
 with channels as materialized(select*from pro_lead_origin_catalog(p_actor)where archived=(p_status='archived')and(btrim(p_query)=''or exists(select 1 from unnest(pro_lead_origin_name_aliases(id,name,custom_name))alias where position(lower(btrim(p_query))in alias)>0))),metadata as(select md5(p_actor::text||p_status||p_query||coalesce(jsonb_agg(to_jsonb(c)order by id)::text,'[]'))token from channels c),page as(select*from channels where p_after is null or id>p_after order by id limit 21)
 select jsonb_build_object('fingerprint',(select token from metadata),'items',coalesce((select jsonb_agg(pro_lead_origin_channel_json(p_actor,id)order by id)from(select*from page order by id limit 20)p),'[]'),'nextCursor',case when(select count(*)from page)>20 then(select id from page order by id offset 19 limit 1)else null end,'validCursor',p_after is null or exists(select 1 from channels where id=p_after))into answer;
 if p_after is not null and(p_snapshot is distinct from answer->>'fingerprint'or not(answer->>'validCursor')::boolean)then raise exception'Channels changed'using errcode='40001';end if;return answer-'validCursor';end $$;
-- Only the six explicit built-in translations are aliases; never infer channels.
create or replace function public.pro_lead_origin_name_aliases(p_id text,p_name text,p_custom boolean)returns text[]language sql immutable security invoker set search_path=public,pg_temp as $$select array_remove(array[lower(btrim(p_name)),case when not p_custom then lower(case p_id when'direct'then'Contacto directo'when'referral'then'Recomendación'when'website'then'Sitio web'when'social'then'Redes sociales'when'advertising'then'Publicidad'when'other'then'Otro'end)else null end],null)$$;
create or replace function public.pro_lead_origin_mutate(p_actor uuid,p_input jsonb)returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;act text;cid text;rev integer;r pro_lead_origin_actions;before_json jsonb;after_json jsonb;answer jsonb;keys text[];expected text[];n text;k text;lid uuid;current_row pro_lead_origin_assignments;had_row boolean;begin
 perform pro_lead_origin_owner(p_actor);if jsonb_typeof(p_input)is distinct from'object'or jsonb_typeof(p_input->'action')is distinct from'string'or jsonb_typeof(p_input->'actionId')is distinct from'string'or jsonb_typeof(p_input->'revision')is distinct from'number'or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false)or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception'Invalid origin action'using errcode='22023';end if;
 act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 expected:=case act when'channel_create'then array['action','actionId','channelId','name','revision']when'channel_rename'then array['action','actionId','channelId','name','revision']when'channel_archive'then array['action','actionId','channelId','revision']when'channel_restore'then array['action','actionId','channelId','revision']when'assign'then array['action','actionId','channelId','channelRevision','id','kind','revision']when'clear'then array['action','actionId','id','kind','revision']else null end;
 select array_agg(key order by key)into keys from jsonb_object_keys(p_input)key;if expected is null or keys<>expected then raise exception'Invalid action fields'using errcode='22023';end if;
 if act<>'clear'then cid:=p_input->>'channelId';if jsonb_typeof(p_input->'channelId')is distinct from'string'or cid not in('direct','referral','website','social','advertising','other')and cid!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'then raise exception'Invalid channel'using errcode='22023';end if;end if;
 if act in('channel_create','channel_rename')then if jsonb_typeof(p_input->'name')is distinct from'string'then raise exception'Invalid name'using errcode='22023';end if;n:=btrim(p_input->>'name');if length(n)not between 1 and 80 or n~'[[:cntrl:]]'then raise exception'Invalid name'using errcode='22023';end if;end if;
 if act in('assign','clear')then k:=p_input->>'kind';if k is null or k not in('manual','request')or jsonb_typeof(p_input->'id')is distinct from'string'then raise exception'Invalid lead'using errcode='22023';end if;lid:=(p_input->>'id')::uuid;end if;
 if act='assign'and(jsonb_typeof(p_input->'channelRevision')is distinct from'number'or not coalesce(p_input->>'channelRevision'~'^[0-9]{1,10}$',false)or(p_input->>'channelRevision')::numeric not between 0 and 2147483647)then raise exception'Invalid channel revision'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-origin-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-origin-catalog:'||p_actor::text,0));perform pro_lead_origin_owner(p_actor);
 select*into r from pro_lead_origin_actions where owner_id=p_actor and action_id=aid;if found then if r.result->>'type'='origin'then perform pro_lead_origin_get(p_actor,r.input->>'kind',(r.input->>'id')::uuid);end if;if r.input is distinct from p_input then raise exception'Action identity reused'using errcode='22023';end if;return r.result;end if;
 if act like'channel_%'then
 before_json:=pro_lead_origin_channel_json(p_actor,cid);
 if act='channel_create'then if rev<>0 or before_json is not null or cid in('direct','referral','website','social','advertising','other')then raise exception'Channel identity exists'using errcode='40001';end if;
 else if before_json is null or(before_json->>'revision')::integer<>rev then raise exception'Channel changed'using errcode='40001';end if;if act='channel_restore'then if not(before_json->>'archived')::boolean then raise exception'Channel is not archived'using errcode='22023';end if;elsif(before_json->>'archived')::boolean then raise exception'Restore the channel before changing it'using errcode='40001';end if;end if;
 if act in('channel_create','channel_rename','channel_restore')and exists(select 1 from pro_lead_origin_catalog(p_actor)c where c.id<>cid and not c.archived and pro_lead_origin_name_aliases(c.id,c.name,c.custom_name)&&pro_lead_origin_name_aliases(cid,coalesce(n,before_json->>'name'),case when act in('channel_create','channel_rename')then true else coalesce((before_json->>'customName')::boolean,true)end))then raise exception'An active channel already uses this name'using errcode='40001';end if;
 insert into pro_lead_origin_channels(owner_id,id,name_override,archived,revision,created_at,updated_at)values(p_actor,cid,case when act in('channel_create','channel_rename')then n when coalesce((before_json->>'customName')::boolean,false)then before_json->>'name'else null end,act='channel_archive',rev+1,now(),now())on conflict(owner_id,id)do update set name_override=case when act='channel_rename'then n else pro_lead_origin_channels.name_override end,archived=case when act='channel_archive'then true when act='channel_restore'then false else pro_lead_origin_channels.archived end,revision=rev+1,created_at=coalesce(pro_lead_origin_channels.created_at,now()),updated_at=now();
 after_json:=pro_lead_origin_channel_json(p_actor,cid);answer:=jsonb_build_object('type','channel','action',act,'channel',after_json,'before',before_json);
 else
 perform pg_advisory_xact_lock(hashtextextended('pro-lead-origin:'||p_actor::text||':'||k||':'||lid::text,0));
 -- Manual commercial writers share owner->lead order. Public requests are only
 -- read/rechecked, avoiding request->work/owner lock inversion in booking writers.
 if k='manual'then perform 1 from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=lid for update;end if;
 perform pro_lead_origin_owner(p_actor);before_json:=pro_lead_origin_get(p_actor,k,lid);if not(before_json->>'canWrite')::boolean or(before_json->>'revision')::integer<>rev then raise exception'Lead attribution changed or is read-only'using errcode='40001';end if;
 if act='assign'then after_json:=pro_lead_origin_channel_json(p_actor,cid);if after_json is null or(after_json->>'archived')::boolean or(after_json->>'revision')::integer<>(p_input->>'channelRevision')::integer then raise exception'Choose a current active channel'using errcode='40001';end if;
 end if;
 select*into current_row from pro_lead_origin_assignments where owner_id=p_actor and kind=k and id=lid for update;had_row:=found;if had_row and current_row.revision<>rev or not had_row and rev<>0 then raise exception'Attribution changed'using errcode='40001';end if;
 insert into pro_lead_origin_assignments(owner_id,kind,id,manual_id,request_id,channel_id,revision)values(p_actor,k,lid,case when k='manual'then lid else null end,case when k='request'then lid else null end,case when act='assign'then cid else null end,rev+1)on conflict(owner_id,kind,id)do update set channel_id=excluded.channel_id,revision=excluded.revision,updated_at=now();
 after_json:=pro_lead_origin_get(p_actor,k,lid);if not(after_json->>'canWrite')::boolean then raise exception'Lead became read-only'using errcode='40001';end if;answer:=jsonb_build_object('type','origin','action',act,'origin',after_json,'before',before_json);insert into pro_lead_origin_history(owner_id,kind,id,action_id,action,before_origin,after_origin)values(p_actor,k,lid,aid,act,before_json,after_json);
 end if;
 perform pro_lead_origin_owner(p_actor);insert into pro_lead_origin_actions(owner_id,action_id,input,result)values(p_actor,aid,p_input,answer);return answer;end $$;
create or replace function public.pro_lead_origin_list(p_actor uuid,p_status text default 'active',p_stage text default null,p_query text default '',p_channel text default null,p_after text default null,p_snapshot text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare catalog jsonb;answer jsonb;actual_token text;cursor_valid boolean;begin
 perform pro_lead_origin_owner(p_actor);catalog:=pro_lead_origin_stage_catalog(p_actor);if p_status is null or p_status not in('active','archived') or p_query is null or length(p_query)>100 or p_stage is not null and not exists(select 1 from jsonb_array_elements(catalog->'stages')s where s->>'id'=p_stage) or p_after is not null and p_after!~'^(manual|request):[a-f0-9-]{36}$' then raise exception 'Invalid lead query' using errcode='22023';end if;
 if(p_after is null)<>(p_snapshot is null)or(p_channel is not null and p_channel<>'unspecified'and pro_lead_origin_channel_json(p_actor,p_channel)is null)then raise exception'Invalid attribution filter'using errcode='22023';end if;
 with sources as materialized(select s.*,a.channel_id,coalesce(a.revision,0)origin_revision,case when s.kind='request'then exists(select 1 from pro_clients c join pro_appointment_requests r on r.owner_id=c.user_id and c.id='reservation-'||r.client_user_id::text where r.owner_id=p_actor and r.id=s.id and c.archived)else false end private_client_archived from pro_lead_center_sources(p_actor,p_status='archived',p_query)s left join pro_lead_origin_assignments a on a.owner_id=p_actor and a.kind=s.kind and a.id=s.id where p_channel is null or p_channel='unspecified'and a.channel_id is null or a.channel_id=p_channel),
 metadata as(select md5(p_actor::text||p_status||coalesce(p_stage,'all')||p_query||coalesce(p_channel,'all')||catalog::text||(select coalesce(jsonb_agg(to_jsonb(c)order by id)::text,'[]')from pro_lead_origin_catalog(p_actor)c)||coalesce(string_agg(jsonb_build_array(kind,id,created_at,effective_stage,fingerprint,channel_id,origin_revision,private_client_archived)::text,',' order by created_at desc,kind,id desc),''))token from sources),
 anchor as(select * from sources where kind=split_part(p_after,':',1) and id=split_part(p_after,':',2)::uuid and(p_stage is null or effective_stage=p_stage)),
 selected as materialized(select * from sources where(p_stage is null or effective_stage=p_stage) and(p_after is null or created_at<(select created_at from anchor) or created_at=(select created_at from anchor) and(kind>(select kind from anchor) or kind=(select kind from anchor) and id<(select id from anchor))) order by created_at desc,kind,id desc limit 21),
 page as(select coalesce(jsonb_agg(pro_lead_origin_item(p_actor,kind,id) order by created_at desc,kind,id desc),'[]'::jsonb)items from(select * from selected order by created_at desc,kind,id desc limit 20)v),
 counts as(select jsonb_agg(jsonb_build_object('stageId',s->>'id','count',(select count(*) from sources where effective_stage=s->>'id')) order by(s->>'position')::integer)items from jsonb_array_elements(catalog->'stages')s)
 select jsonb_build_object('catalog',catalog,'items',page.items,'counts',counts.items,'nextCursor',case when(select count(*) from selected)>20 then(select kind||':'||id::text from selected order by created_at desc,kind,id desc offset 19 limit 1)else null end,'snapshotToken',metadata.token),metadata.token,(p_after is null or exists(select 1 from anchor)) into answer,actual_token,cursor_valid from page cross join counts cross join metadata;
 if p_after is not null and(p_snapshot is null or p_snapshot<>actual_token or not cursor_valid) then raise exception 'Leads changed; refresh before continuing' using errcode='40001';end if;return jsonb_build_object('page',answer,'context',coalesce((select jsonb_agg(pro_lead_origin_get(p_actor,i->>'kind',(i->>'id')::uuid)order by n)from jsonb_array_elements(answer->'items')with ordinality x(i,n)),'[]'));end $$;
create or replace function public.pro_lead_origin_metrics(p_actor uuid,p_status text default'active',p_stage text default null,p_query text default'',p_from date default null,p_to date default null,p_after text default null,p_snapshot text default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare answer jsonb;catalog jsonb;begin
 perform pro_lead_origin_owner(p_actor);catalog:=pro_lead_origin_stage_catalog(p_actor);
 if p_status is null or p_status not in('active','archived')or p_query is null or length(p_query)>100 or p_stage is not null and not exists(select 1 from jsonb_array_elements(catalog->'stages')s where s->>'id'=p_stage)or(p_after is null)<>(p_snapshot is null)or p_from is not null and p_from not between date'1900-01-01'and date'2100-12-31'or p_to is not null and p_to not between date'1900-01-01'and date'2100-12-31'or p_from>p_to then raise exception'Invalid metrics query'using errcode='22023';end if;
 with sources as materialized(select s.*,a.channel_id,coalesce(a.revision,0)origin_revision,case when s.kind='request'then exists(select 1 from pro_clients c join pro_appointment_requests r on r.owner_id=c.user_id and c.id='reservation-'||r.client_user_id::text where r.owner_id=p_actor and r.id=s.id and c.archived)else false end private_client_archived from pro_lead_center_sources(p_actor,p_status='archived',p_query)s left join pro_lead_origin_assignments a on a.owner_id=p_actor and a.kind=s.kind and a.id=s.id where(p_stage is null or s.effective_stage=p_stage)and(p_from is null or(s.created_at at time zone'America/Costa_Rica')::date>=p_from)and(p_to is null or(s.created_at at time zone'America/Costa_Rica')::date<=p_to)),
 groups as(select channel_id,count(*)filter(where kind='manual')manual,count(*)filter(where kind='request')request,count(*)total,count(*)filter(where effective_stage='won')won from sources group by channel_id),
 rows as(select 'unspecified'::text id,'0'::text ordering,null::text channel_id,coalesce(g.manual,0)manual,coalesce(g.request,0)request,coalesce(g.total,0)total,coalesce(g.won,0)won from(select 1)dummy left join groups g on g.channel_id is null union all select channel_id,'1:'||channel_id,channel_id,manual,request,total,won from groups where channel_id is not null),
 metadata as(select md5(p_actor::text||p_status||coalesce(p_stage,'all')||p_query||coalesce(p_from::text,'')||coalesce(p_to::text,'')||catalog::text||(select coalesce(jsonb_agg(to_jsonb(c)order by id)::text,'[]')from pro_lead_origin_catalog(p_actor)c)||coalesce(jsonb_agg(jsonb_build_array(kind,id,fingerprint,effective_stage,channel_id,origin_revision,private_client_archived)order by created_at desc,kind,id desc)::text,'[]'))token from sources),
 page as(select*from rows where p_after is null or ordering>(case when p_after='unspecified'then'0'else'1:'||p_after end)order by ordering limit 21)
 select jsonb_build_object('fingerprint',(select token from metadata),'items',coalesce((select jsonb_agg(jsonb_build_object('channel',pro_lead_origin_channel_json(p_actor,channel_id),'manual',manual,'request',request,'total',total,'won',won)order by ordering)from(select*from page order by ordering limit 20)p),'[]'),'totals',(select jsonb_build_object('manual',count(*)filter(where kind='manual'),'request',count(*)filter(where kind='request'),'total',count(*),'won',count(*)filter(where effective_stage='won'))from sources),'nextCursor',case when(select count(*)from page)>20 then(select id from page order by ordering offset 19 limit 1)else null end,'validCursor',p_after is null or exists(select 1 from rows where id=p_after))into answer;
 if p_after is not null and(p_snapshot is distinct from answer->>'fingerprint'or not(answer->>'validCursor')::boolean)then raise exception'Metrics changed'using errcode='40001';end if;return answer-'validCursor';end $$;
create or replace function public.pro_lead_origin_immutable()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin raise exception'Immutable commercial attribution audit'using errcode='23514';end $$;
drop trigger if exists pro_lead_origin_actions_immutable on pro_lead_origin_actions;
create trigger pro_lead_origin_actions_immutable before update on pro_lead_origin_actions for each row execute function pro_lead_origin_immutable();
drop trigger if exists pro_lead_origin_history_immutable on pro_lead_origin_history;
create trigger pro_lead_origin_history_immutable before update on pro_lead_origin_history for each row execute function pro_lead_origin_immutable();
alter table pro_lead_origin_channels enable row level security;alter table pro_lead_origin_assignments enable row level security;alter table pro_lead_origin_actions enable row level security;alter table pro_lead_origin_history enable row level security;
revoke all on pro_lead_origin_channels,pro_lead_origin_assignments,pro_lead_origin_actions,pro_lead_origin_history from public,anon,authenticated;grant all on pro_lead_origin_channels,pro_lead_origin_assignments,pro_lead_origin_actions,pro_lead_origin_history to service_role;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname like'pro_lead_origin_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst,'reload schema';
